/* Group G09 mastery bank: Research methods (correlations), Development (early brain, Three mountains), Memory (reductionism and holism), Psychological problems (symptoms, CBT, drugs), Social influence (culture, bystanders, crowds). Original questions, not copied from past papers. */
(function () {
  'use strict';
  var B = window.MASTERY_BANKS = window.MASTERY_BANKS || {};
  var R = window.Mastery;   // R.roundDp(x, dp), R.roundSf(x, n)

  function rint(a, b) { return a + Math.floor(Math.random() * (b - a + 1)); }
  function pick(a) { return a[Math.floor(Math.random() * a.length)]; }
  function shuf(a) { a = a.slice(); for (var i = a.length - 1; i > 0; i--) { var j = Math.floor(Math.random() * (i + 1)); var t = a[i]; a[i] = a[j]; a[j] = t; } return a; }
  // Single-answer item: the correct option is written first (the engine shuffles the options).
  function mc(skill, q, right, wrongs, why, x) {
    var r = { skill: skill, kind: 'mcq', q: q, options: [right].concat(wrongs), answer: 0, why: why };
    if (x) for (var k in x) r[k] = x[k];
    return r;
  }
  // Select-all item: the correct options are written first.
  function ms(skill, q, rights, wrongs, why, x) {
    var ans = []; for (var i = 0; i < rights.length; i++) ans.push(i);
    var r = { skill: skill, kind: 'multi', q: q, options: rights.concat(wrongs), answers: ans, why: why };
    if (x) for (var k in x) r[k] = x[k];
    return r;
  }
  function table(head, rows) {
    var h = '<table class="mc-table"><tr>' + head.map(function (c) { return '<th>' + c + '</th>'; }).join('') + '</tr>';
    rows.forEach(function (r) { h += '<tr>' + r.map(function (c) { return '<td>' + c + '</td>'; }).join('') + '</tr>'; });
    return h + '</table>';
  }
  // Scatter diagram: x 0-10 (grid every 2), y 0-100 (grid every 10). pts = [[x, y], ...]
  function scatter(pts, xl, yl, label) {
    var s = '<svg viewBox="0 0 320 240" role="img" aria-label="' + label + '"><rect width="320" height="240" fill="#fff"/>';
    var X = function (v) { return 50 + v * 25; }, Y = function (v) { return 200 - v * 1.8; };
    for (var g = 0; g <= 100; g += 10) {
      s += '<line x1="50" y1="' + Y(g) + '" x2="300" y2="' + Y(g) + '" stroke="#9aa5b8" stroke-width="0.5"/>';
      s += '<text x="44" y="' + (Y(g) + 3) + '" font-size="9" text-anchor="end" fill="#303a4c">' + g + '</text>';
    }
    for (var h = 0; h <= 10; h += 2) {
      s += '<line x1="' + X(h) + '" y1="20" x2="' + X(h) + '" y2="200" stroke="#9aa5b8" stroke-width="0.5"/>';
      s += '<text x="' + X(h) + '" y="212" font-size="9" text-anchor="middle" fill="#303a4c">' + h + '</text>';
    }
    s += '<line x1="50" y1="20" x2="50" y2="200" stroke="#303a4c" stroke-width="1.5"/><line x1="50" y1="200" x2="300" y2="200" stroke="#303a4c" stroke-width="1.5"/>';
    pts.forEach(function (p) { s += '<circle cx="' + X(p[0]) + '" cy="' + Y(p[1]) + '" r="4" fill="#e4464f"/>'; });
    s += '<text x="175" y="233" font-size="10" text-anchor="middle" fill="#303a4c">' + xl + '</text>';
    s += '<text x="12" y="110" font-size="10" text-anchor="middle" fill="#303a4c" transform="rotate(-90 12 110)">' + yl + '</text></svg>';
    return s;
  }
  function distinctXs(n) { var all = []; for (var v = 0.5; v <= 9.5; v += 0.5) all.push(v); return shuf(all).slice(0, n).sort(function (a, b) { return a - b; }); }

  /* ---------- PSY-RM-08 Correlations and scatter diagrams ---------- */
  var rm08 = [];
  // generated scatter-diagram items
  rm08.push({ skill: 'read scatter diagram', gen: function () {
    var T, pts, n, who, sc;
    do {
      pts = []; n = 0; T = pick([40, 50, 60, 70]);
      distinctXs(12).forEach(function (x) { var y; do { y = rint(15, 92); } while (Math.abs(y - T) < 4); pts.push([x, y]); if (y > T) n++; });
    } while (n < 3 || n > 9);
    who = pick(['students', 'trainee bakers', 'swimmers']); sc = pick(['test score', 'practical mark', 'skills score']);
    return { kind: 'num', unit: '', answer: n, display: String(n), family: 'rm08count',
      q: 'A teacher plotted the hours of practice and the ' + sc + ' of 12 ' + who + '. Each point is one person.<br>How many of the ' + who + ' scored <b>more than ' + T + '</b>?',
      svg: scatter(pts, 'Hours of practice per week', sc.charAt(0).toUpperCase() + sc.slice(1), 'Scatter diagram of practice hours against ' + sc),
      why: 'Follow the ' + T + ' grid line across and count the points above it: there are ' + n + '. The other ' + (12 - n) + ' points are below it. Each point is one person, so count every point once.' };
  } });
  rm08.push({ skill: 'identify direction from a graph', gen: function () {
    var kind = pick(['pos', 'neg', 'none']), xs = distinctXs(12), pts = [];
    xs.forEach(function (x, i) {
      var y;
      if (kind === 'pos') y = 12 + 8 * x + rint(-7, 7);
      else if (kind === 'neg') y = 90 - 8 * x + rint(-7, 7);
      else y = (i % 2 === 0) ? rint(66, 80) : rint(20, 34);
      pts.push([x, Math.max(6, Math.min(96, y))]);
    });
    var pair = pick([['Hours of exercise per week', 'Mood rating', 'exercise and mood'], ['Hours of screen time per day', 'Sleep score', 'screen time and sleep'], ['Hours of revision per week', 'Test mark', 'revision and test marks']]);
    var right = kind === 'pos' ? 'A positive correlation' : kind === 'neg' ? 'A negative correlation' : 'No correlation';
    var why = kind === 'pos' ? 'The points rise from bottom left to top right: as the first co-variable goes up, so does the second. That is a positive correlation.'
      : kind === 'neg' ? 'The points fall from top left to bottom right: as the first co-variable goes up, the second goes down. That is a negative correlation.'
      : 'The points are scattered with no clear upward or downward pattern, so there is no correlation.';
    return { kind: 'mcq', q: 'The scatter diagram shows the link between ' + pair[2] + ' for 12 people. What does it show?',
      svg: scatter(pts, pair[0], pair[1], 'Scatter diagram of ' + pair[2]),
      options: [right, kind === 'pos' ? 'A negative correlation' : 'A positive correlation', kind === 'none' ? 'A negative correlation' : 'No correlation', 'Cause and effect between the two variables'], answer: 0, why: why };
  } });
  rm08.push({ skill: 'identify direction from data', gen: function () {
    var p = pick([
      { a: 'hours of sleep', b: 'mistakes on a memory task', av: [4, 5, 6, 7, 8, 9], neg: true },
      { a: 'minutes of daily reading', b: 'vocabulary score', av: [10, 20, 30, 40, 50, 60], neg: false },
      { a: 'hours of TV watched', b: 'minutes of homework done', av: [1, 2, 3, 4, 5, 6], neg: true },
      { a: 'hours spent practising', b: 'goals scored in matches', av: [2, 4, 6, 8, 10, 12], neg: false }]);
    var bs = [], v = rint(2, 6);
    for (var i = 0; i < 6; i++) { bs.push(v); v += rint(2, 3); }
    if (p.neg) bs.reverse();
    var rows = shuf([0, 1, 2, 3, 4, 5]).map(function (i, k) { return ['P' + (k + 1), p.av[i], bs[i]]; });
    var cap = function (t) { return t.charAt(0).toUpperCase() + t.slice(1); };
    return { kind: 'mcq', q: 'A psychologist measured ' + p.a + ' and ' + p.b + ' in six people.<br>' + table(['Person', cap(p.a), cap(p.b)], rows) + 'What type of correlation do these data show?',
      options: [p.neg ? 'Negative' : 'Positive', p.neg ? 'Positive' : 'Negative', 'None', 'The first variable causes the second'], answer: 0,
      why: 'Put the people in order of the first column. As ' + p.a + ' goes up, ' + p.b + ' goes ' + (p.neg ? 'down' : 'up') + ' every time, so the correlation is ' + (p.neg ? 'negative' : 'positive') + '. A correlation cannot show cause.' };
  } });
  rm08.push({ skill: 'read scatter diagram', gen: function () {
    var xs = distinctXs(14).filter(function (x) { return x !== 6; }), Ty = pick([40, 50, 60]), pts = [], n = 0, tries = 0;
    do {
      pts = []; n = 0;
      xs.forEach(function (x) { var y; do { y = rint(15, 92); } while (Math.abs(y - Ty) < 4); pts.push([x, y]); if (x > 6 && y > Ty) n++; });
      tries++;
    } while ((n < 2 || n > 6) && tries < 200);
    return { kind: 'num', unit: '', answer: n, display: String(n), family: 'rm08count',
      q: 'The scatter diagram shows the hours a group of cyclists trained each week and their time-trial score. How many cyclists trained for <b>more than 6 hours</b> <b>and</b> scored <b>more than ' + Ty + '</b>?',
      svg: scatter(pts, 'Hours of training per week', 'Time-trial score', 'Scatter diagram of training hours against time-trial score'),
      why: 'First look to the right of 6 on the horizontal axis, then count only the points in that area that are also above ' + Ty + ' on the vertical axis. There are ' + n + '.' };
  } });
  // static items
  rm08.push(mc('definition', 'Which statement best defines the <b>correlation method</b>?', 'A method that measures whether two co-variables are related to each other', ['A method where the researcher changes one variable to see its effect on another', 'A method that proves one variable causes a change in another', 'A method where the researcher watches behaviour without measuring anything'], 'A correlation measures two co-variables and checks whether they are related. Nothing is manipulated, and it cannot prove cause.'));
  rm08.push(mc('definition', 'In a correlation study, what are the <b>co-variables</b>?', 'The two variables that are both measured to see whether they are related', ['The independent variable that is changed and the dependent variable that is measured', 'The variables that the researcher controls in the study', 'The two groups of participants who are compared'], 'Co-variables are the two measured variables. Correlations have no IV or DV because neither variable is manipulated.'));
  rm08.push(mc('co-variables not IV/DV', 'A researcher records the number of friends 40 adults have and their score on a wellbeing questionnaire. How should the two measures be described?', 'Both are co-variables, because neither is manipulated by the researcher', ['The number of friends is the IV and wellbeing is the DV', 'Wellbeing is the IV because it is the score the researcher measures at the end', 'Both are extraneous variables that need controlling'], 'In a correlation both variables are simply measured. The researcher does not change either, so there is no IV or DV.'));
  rm08.push(mc('causation', 'A study finds a positive correlation between the number of ice creams sold at a beach and the number of people who get sunburnt. What is the best conclusion?', 'A third variable, such as hot sunny weather, could be causing both to rise', ['Eating ice cream causes people to get sunburnt', 'Getting sunburnt makes people want to buy ice cream', 'The correlation must be a mistake, because ice cream and sunburn are completely unrelated'], 'A correlation shows a relationship but not cause and effect. Hot weather (a third variable) is a likely reason for both increases.'));
  rm08.push(mc('causation', 'Sana finds a strong negative correlation between hours of sleep and number of colds in a group of students. Which conclusion is <b>not</b> justified by the correlation alone?', 'Getting less sleep makes students catch more colds', ['Students who sleep fewer hours tend to have more colds', 'Sleep and number of colds are related in this group', 'As hours of sleep increase, the number of colds tends to fall'], 'A correlation can describe the pattern in the data, but it cannot show that one variable causes the other.'));
  rm08.push(mc('describe relationship', 'Which answer describes a negative correlation between hours of gaming and hours of sleep?', 'The more hours people game, the fewer hours they sleep', ['The more hours people game, the more hours they sleep', 'Gaming for more hours makes people ill and tired', 'Hours of gaming do not match hours of sleep in any pattern'], 'In a negative correlation, as one co-variable increases the other decreases. Name both variables in your answer.'));
  rm08.push(mc('describe relationship', 'Which sentence is the best description of a positive correlation between height and arm span?', 'People with greater height tend to have a greater arm span', ['People who are taller tend to have a much shorter arm span than others', 'Increasing height causes arm span to grow longer', 'Height and arm span are measured but are not related'], 'A positive correlation means both co-variables increase together. The correct sentence names both variables and the direction.'));
  rm08.push(mc('scatter diagram features', 'On a scatter diagram of exercise time and fitness score for 20 people, what does <b>each point</b> represent?', 'One participant, with their score on each co-variable', ['The mean score of all twenty participants', 'One group of participants in the study', 'The most common score shared by all of the participants'], 'Each point shows one participant\'s pair of scores, one on the horizontal axis and one on the vertical axis.'));
  rm08.push(mc('scatter diagram features', 'A scatter diagram has 15 points. How many participants took part?', 'Fifteen, because each point is one participant', ['Thirty, because every participant gives two points', 'Two, because there are two axes', 'It is impossible to tell from the number of points'], 'Each participant gives one pair of scores, which is one point. 15 points means 15 participants.'));
  rm08.push(mc('applying direction', 'Which of these studies would most likely produce a <b>negative</b> correlation?', 'Comparing the hours of social media used per day and scores on a body-image scale, where higher scores mean better body image', ['Comparing minutes of daily practice and scores on a piano exam', 'Comparing the age of children and the number of words they know', 'Comparing hours of sunshine in a month and number of ice creams sold'], 'A negative correlation means as one goes up, the other goes down. The other pairs would be expected to rise together.'));
  rm08.push(mc('applying direction', 'Marcus predicts that the more kilometres a runner trains each week, the lower their 5 km race time will be. What type of correlation is he predicting?', 'Negative', ['Positive', 'No correlation', 'Causal'], 'Weekly distance is expected to go up while race time goes down, so he predicts a negative correlation.'));
  rm08.push(mc('applying direction', 'A study found that older children in a primary school tend to have larger shoe sizes. Which type of correlation is this?', 'Positive, because both age and shoe size increase together', ['Negative, because shoe size changes as age changes', 'Positive, because age is the independent variable and shoe size is the dependent variable', 'No correlation, because age and shoe size are different things'], 'Both co-variables rise together, which is a positive correlation. The reason is not part of the definition.'));
  rm08.push(mc('conclusion from data', 'Dev finds that students who spend under 30 minutes a day reading score 3 or less on a vocabulary test, while students who read over 2 hours a day mostly score 8 or above. Which conclusion does this support?', 'The more time students spend reading, the higher their vocabulary score tends to be', ['Reading for a longer time causes students\' vocabulary scores to increase by a large amount', 'The more students read, the lower their vocabulary score', 'Reading time and vocabulary score are not linked'], 'The data show scores rising as reading time rises, which supports a positive relationship. It does not prove that reading causes the higher scores.'));
  rm08.push(mc('conclusion from data', 'A researcher finds that people who drink more cups of coffee a day tend to report sleeping fewer hours. Which statement correctly supports a negative relationship?', 'As coffee intake rises, hours of sleep fall', ['As coffee intake rises, hours of sleep also rise', 'Coffee drinkers sleep badly because of caffeine', 'People who sleep less drink more coffee because they are tired'], 'To support a negative relationship, say that one measure rises while the other falls, using the variable names. The other options are positive or give a cause.'));
  rm08.push(mc('strengths and weaknesses', 'Why might a psychologist choose a correlation rather than an experiment to study the link between stress and illness?', 'It would be unethical to deliberately make people stressed', ['It allows the researcher to prove that stress causes illness', 'It makes it possible to control all extraneous variables', 'It lets the researcher manipulate how much stress people have'], 'Correlations are useful when manipulating a variable would be unethical or impossible. They cannot show cause or give tight control.'));
  rm08.push(mc('strengths and weaknesses', 'What is the main weakness of the correlation method?', 'It cannot show that one variable causes the other', ['It always needs a very large sample', 'It cannot be used with numerical data', 'It changes participants\' behaviour by manipulating a variable'], 'Because no variable is manipulated and others are not controlled, a correlation cannot show cause and effect.'));
  rm08.push(mc('strengths and weaknesses', 'Which is a strength of using the correlation method?', 'It can show whether a relationship exists without the researcher having to manipulate anything', ['It can show which variable is the cause and which is the effect', 'It controls every other variable that might affect the results', 'It always has a higher validity than an experiment'], 'A correlation can reveal relationships, including ones that would be unethical or impractical to test experimentally, but it cannot show cause.'));
  rm08.push(mc('third variable', 'Pupils who own more books score higher in exams. A researcher says that owning books raises exam scores. What is the problem with this claim?', 'A third variable, such as parents\' interest in education, could affect both', ['Exam scores cannot be measured accurately', 'The number of books owned is a dependent variable', 'A negative correlation has been mistaken for a positive one'], 'A correlation does not show cause. A third variable such as parental support could explain why both book ownership and scores are high.'));
  rm08.push(ms('knowledge of correlation', 'Select <b>all</b> the statements that are true about correlations.', ['Both variables are measured, not manipulated', 'A positive correlation means both variables tend to increase together', 'A correlation does not prove that one variable causes the other'], ['A negative correlation means the two variables are not related', 'A correlation has an independent variable and a dependent variable', 'A scatter diagram always has a straight line through every point'], 'In a correlation both co-variables are measured, direction describes how they change together, and cause cannot be shown. A negative correlation is still a relationship and there is no IV or DV.'));
  rm08.push(ms('co-variables', 'A psychologist plans a correlation study. Select <b>all</b> pairs that could be the two co-variables.', ['Age in years and number of words known', 'Hours of exercise a week and score on a stress scale'], ['Type of drink given (coffee or water) and reaction time', 'Group (noisy room or quiet room) and number of words recalled', 'Time of day the test is given and time spent in the lab'], 'Co-variables are two measured scores that can be put on a scatter diagram. The other pairs involve a condition chosen by the researcher, so they belong to an experiment.'));
  rm08.push(mc('scatter diagram features', 'Which description shows the correct way to read a scatter diagram to decide the type of correlation?', 'Look at the overall direction of the points from left to right', ['Look only at the highest point and the lowest point on the graph', 'Join the first and last point and ignore the rest', 'Count the number of points above the middle gridline'], 'The type of correlation is shown by the overall direction of the pattern: rising means positive, falling negative, no pattern means none.'));
  rm08.push(mc('no correlation', 'A scatter diagram of shoe size and score on a maths test shows points scattered all over with no pattern. What should the researcher conclude?', 'There is no correlation between shoe size and maths test score', ['There is a weak positive correlation because a few points rise together', 'Shoe size causes lower maths scores', 'There is a negative correlation because the graph is untidy'], 'A graph with no pattern in the points shows no correlation: knowing one score tells you nothing about the other.'));
  rm08.push(mc('explain a conclusion', 'Lena finds that the more time teenagers spend on their phones at night, the lower their sleep quality scores. Which answer is a full explanation of a conclusion she can draw?', 'Teenagers who use their phones more at night tend to sleep worse, as sleep quality scores fall when phone time rises', ['Phone use at night causes teenagers to sleep badly, as sleep quality scores fall', 'Teenagers sleep badly, so they use their phones for more time at night', 'There is a negative correlation, so the results are reliable'], 'A full answer gives the conclusion and then supports it using the pattern in the data. Claims about cause or reliability are not supported by a correlation.'));
  B['PSY-RM-08'] = { title: 'Correlations and scatter diagrams', items: rm08 };

  /* ---------- PSY-DEV-05 How the brain develops before birth ---------- */
  var dev05 = [];
  var embryoSvg = '<svg viewBox="0 0 300 130" role="img" aria-label="Side view of an early developing brain with three swellings labelled A, B and C from front to back"><rect width="300" height="130" fill="#fff"/><ellipse cx="75" cy="60" rx="58" ry="40" fill="#9aa5b8" stroke="#303a4c" stroke-width="2"/><ellipse cx="160" cy="62" rx="36" ry="28" fill="#9aa5b8" stroke="#303a4c" stroke-width="2"/><ellipse cx="235" cy="66" rx="42" ry="30" fill="#9aa5b8" stroke="#303a4c" stroke-width="2"/><text x="75" y="66" font-size="22" font-weight="bold" text-anchor="middle" fill="#303a4c">A</text><text x="160" y="69" font-size="22" font-weight="bold" text-anchor="middle" fill="#303a4c">B</text><text x="235" y="73" font-size="22" font-weight="bold" text-anchor="middle" fill="#303a4c">C</text><text x="20" y="122" font-size="11" fill="#e4464f">Front of the brain</text><text x="280" y="122" font-size="11" text-anchor="end" fill="#e4464f">Towards the spinal cord</text></svg>';
  dev05.push(mc('structure and origin', 'About three weeks after conception, the neural tube forms swellings. Which list names them?', 'Forebrain, midbrain and hindbrain', ['Cerebrum, cerebellum and medulla', 'Forebrain, cerebellum and spinal cord', 'Midbrain, medulla and cerebrum'], 'The neural tube forms three swellings: the forebrain, midbrain and hindbrain. The cerebellum and medulla develop later, from the hindbrain.'));
  dev05.push(mc('structure and origin', 'Which part of the early brain becomes the cerebrum?', 'The forebrain', ['The midbrain', 'The hindbrain', 'The medulla'], 'The forebrain develops into the cerebrum, the part linked to thinking, planning and language.'));
  dev05.push(mc('structure and origin', 'In the developing brain, the cerebellum and the medulla both develop from which swelling?', 'The hindbrain', ['The forebrain', 'The midbrain', 'The cerebrum'], 'The hindbrain develops into structures including the cerebellum and the medulla.'));
  dev05.push(ms('structure and origin', 'Select <b>all</b> the structures that develop from the hindbrain.', ['The cerebellum', 'The medulla'], ['The cerebrum', 'The neural tube', 'The forebrain'], 'The hindbrain gives rise to the cerebellum and the medulla. The cerebrum comes from the forebrain.'));
  dev05.push(mc('function of regions', 'What is the main job of the cerebellum?', 'Coordinating movement, balance and posture', ['Controlling breathing and heart rate', 'Planning, thinking, language and decision making', 'Carrying signals from the eyes and ears'], 'The cerebellum coordinates movement, balance and posture, which helps skills such as walking. Breathing and heart rate belong to the medulla.'));
  dev05.push(mc('function of regions', 'What is the main job of the medulla?', 'Controlling automatic body functions such as breathing and heart rate', ['Controlling balance when a child learns to walk', 'Thinking, planning and speaking in full sentences, and deciding what to do', 'Storing long-term memories'], 'The medulla controls automatic functions such as breathing and heart rate, which we do not have to think about.'));
  dev05.push(mc('function of regions', 'Which of these jobs is linked to the <b>forebrain</b> as it develops into the cerebrum?', 'Thinking, planning and language', ['Keeping the body balanced', 'Keeping the heartbeat steady', 'Passing signals along the spinal cord'], 'The forebrain becomes the cerebrum, which is involved in thinking, planning and language.'));
  dev05.push(mc('function of regions', 'What does the midbrain do in early development?', 'Links parts of the brain and helps with reflexes to things seen and heard', ['Controls breathing and the heartbeat, and links the brain to the spinal cord', 'Coordinates the muscles for walking', 'Controls planning and speech'], 'The midbrain links parts of the brain together and helps with reflexes such as responding to sights and sounds.'));
  dev05.push(mc('timing', 'According to the specification content, when does the medulla begin forming?', 'Around weeks 6 to 7 of pregnancy', ['About 3 weeks after conception, as the neural tube closes', 'Only after the baby is born', 'Around 9 months, just before birth'], 'The medulla begins forming around weeks 6 to 7 of pregnancy. The three swellings appear earlier, about three weeks after conception.'));
  dev05.push(mc('timing', 'Which statement about the order of early brain development is correct?', 'The forebrain, midbrain and hindbrain swellings form first, and structures such as the cerebellum and medulla develop from them', ['The cerebellum forms first and the forebrain develops from it', 'The medulla forms before the neural tube appears', 'The hindbrain only develops after the baby is born'], 'The three swellings come first. Structures like the cerebellum and medulla then develop from the hindbrain.'));
  dev05.push(mc('misconception check', 'Which statement about the medulla is <b>correct</b>?', 'It controls automatic functions and joins the brain to the spinal cord', ['It controls voluntary thinking and decisions, and develops from the forebrain', 'It coordinates balance and movement', 'It develops from the midbrain'], 'The medulla controls automatic body functions and connects the brain to the spinal cord. Thinking is the job of the cerebrum and balance of the cerebellum.'));
  dev05.push(mc('misconception check', 'A student writes: "The cerebellum is the part of the brain that does our thinking and planning." What is wrong with this?', 'That is the cerebrum; the cerebellum coordinates movement and balance', ['Nothing, because the cerebellum controls thinking', 'The cerebellum controls breathing, not thinking', 'The thinking part of the brain is the medulla'], 'Cerebrum and cerebellum are easy to confuse. The cerebrum (from the forebrain) is for thinking, planning and language; the cerebellum is for coordination, balance and posture.'));
  dev05.push(mc('application', 'Ravi is 16 months old. After a head injury he can no longer keep his balance when he stands, and his arms and legs move in clumsy, uncoordinated ways. Damage to which part of his brain best explains this?', 'The cerebellum', ['The medulla', 'The forebrain swelling', 'The midbrain'], 'The cerebellum coordinates movement, balance and posture. His problems with balance and clumsy movement point to cerebellum damage.'));
  dev05.push(mc('application', 'A newborn girl has trouble keeping a steady heartbeat and breathing without help. Which part of her brain is most likely to be involved?', 'The medulla', ['The cerebellum', 'The cerebrum', 'The neural tube'], 'The medulla controls automatic functions such as breathing and heart rate, so a problem with these suggests the medulla.'));
  dev05.push(mc('application', 'After an accident, Imani, aged 7, finds it hard to plan her homework and to express her ideas in words, but her breathing and walking are normal. Which brain region is most likely to be affected?', 'The cerebrum, which develops from the forebrain', ['The medulla, which develops from the hindbrain', 'The cerebellum, which develops from the hindbrain', 'The spinal cord, which develops from the midbrain'], 'Planning and language are cerebrum functions, and the cerebrum develops from the forebrain. Normal breathing and walking suggest the medulla and cerebellum are working.'));
  dev05.push(mc('application', 'Explaining the effect of damage to the medulla, which answer shows the <b>role</b> and then the <b>effect on the person</b>?', 'It controls automatic functions like breathing, so a baby with damage might struggle to breathe without help', ['It develops from the hindbrain, so damage would affect the baby', 'It is found at the back of the brain, so the baby might feel pain', 'It controls how a baby thinks, so the baby might find it hard to play'], 'A full answer first says what the medulla does (automatic functions like breathing) and then links damage to a result for the person.'));
  dev05.push(mc('application', 'Toby is learning to walk, and his parents see him gradually staying upright with less wobbling. Which part of his developing brain helps with this skill?', 'The cerebellum', ['The medulla', 'The forebrain swelling', 'The neural tube'], 'The cerebellum helps with coordination, balance and posture, which are needed for walking.'));
  dev05.push(mc('structure and origin', 'The medulla joins the brain to what?', 'The spinal cord', ['The cerebrum', 'The eyes and ears', 'The cerebellum only'], 'The medulla connects the brain to the spinal cord, so damage can disrupt signals travelling to and from the body.'));
  dev05.push(mc('function of regions', 'Why can damage to the medulla be so serious for a person?', 'Signals between the brain and body can be disrupted, including those for breathing and heart rate', ['It stops the person from being able to think or speak', 'It only affects how well the person can balance', 'It affects mood but not the body'], 'The medulla controls automatic functions and connects the brain to the spinal cord, so damage can disrupt vital signals to the body.'));
  dev05.push(mc('labelling', 'The diagram shows the three swellings of the early brain, with the front of the brain on the left. Which letter is the <b>forebrain</b>?', 'A', ['B', 'C'], 'The forebrain is the swelling at the front end of the neural tube, labelled A.', { svg: embryoSvg, keepOrder: true, family: 'devfig' }));
  dev05.push(mc('labelling', 'The diagram shows the three swellings of the early brain, with the front of the brain on the left. Which letter is the <b>midbrain</b>?', 'B', ['A', 'C'], 'The midbrain lies between the forebrain (A) and the hindbrain (C), so it is B.', { svg: embryoSvg, keepOrder: true, family: 'devfig' }));
  dev05.push(mc('labelling', 'The diagram shows the three swellings of the early brain, with the front of the brain on the left. The cerebellum and medulla develop from which letter?', 'C', ['A', 'B'], 'The cerebellum and medulla develop from the hindbrain. It is the swelling nearest the spinal cord, labelled C.', { svg: embryoSvg, keepOrder: true, family: 'devfig' }));
  dev05.push(ms('function of regions', 'Select <b>all</b> the functions that are controlled by the medulla.', ['Breathing', 'Heart rate'], ['Balance', 'Language', 'Planning'], 'The medulla controls automatic functions, including breathing and heart rate. Balance is cerebellum; planning and language are cerebrum.'));
  dev05.push(mc('misconception check', 'Which pairing of region and function is correct?', 'Cerebellum: coordination of movement', ['Medulla: coordination of movement', 'Cerebrum: breathing', 'Midbrain: planning and language'], 'The cerebellum coordinates movement. The medulla controls breathing and heart rate, and the cerebrum handles planning and language.'));
  B['PSY-DEV-05'] = { title: 'How the brain develops before birth', items: dev05 };

  /* ---------- PSY-DEV-02 Three mountains task (Piaget and Inhelder, 1956) ---------- */
  var dev02 = [];
  dev02.push(mc('procedure details', 'How many mountains were in the model used by Piaget and Inhelder (1956)?', 'Three', ['Two', 'Four', 'Ten'], 'The task used a model of three mountains. Ten is the number of pictures, not the number of mountains.'));
  dev02.push(mc('procedure details', 'How many pictures of the model, taken from different viewpoints, could the children choose from?', '10', ['3', '8', '20'], 'Children chose from 10 pictures. Do not confuse this with the 3 mountains in the model.'));
  dev02.push(mc('procedure details', 'What was the size of each picture the children could choose from in the Three mountains task?', '20 cm by 28 cm', ['10 cm by 14 cm', '30 cm by 20 cm', '28 cm by 40 cm'], 'Each of the 10 pictures was 20 x 28 cm.'));
  dev02.push(mc('sample', 'How many children took part in total in the Three mountains task of Piaget and Inhelder (1956)?', '100 children', ['10 children', '33 children', '120 children'], 'The sample was 100 children aged about 4 to 12. The figure 33 is only the number aged 8 to 9.'));
  dev02.push(mc('sample', 'How many of the children in the Three mountains study were aged between 8 and 9?', '33', ['10', '100', '20'], 'The sample of 100 children included 33 aged 8 to 9.'));
  dev02.push(mc('sample', 'Which age range did the children in Piaget and Inhelder\'s (1956) study cover?', 'About 4 to 12 years', ['About 0 to 2 years', 'About 13 to 18 years', 'About 2 to 5 years only'], 'The children were aged about 4 to 12, which includes children in the pre-operational and concrete operational stages.'));
  dev02.push(mc('procedure details', 'What was the job of the doll in the Three mountains task?', 'It was placed in different positions around the model so the child had to say what it could see', ['It was a toy given to each child to keep after the test', 'It was placed on top of one mountain to hide it', 'It told the child which picture to choose'], 'The doll was moved around the model. The child had to show the view the doll could see, which tests whether the child can take another person\'s point of view.'));
  dev02.push(mc('procedure details', 'What did each child have to do in the Three mountains task?', 'Choose the picture that showed what the doll could see from where it was placed', ['Write down the name of each mountain on the model', 'Draw the model from their own point of view', 'Explain why the mountains were different heights'], 'The child was shown pictures and had to select the one that matched the doll\'s view of the mountains.'));
  dev02.push(mc('aim and conclusion', 'What was the aim of the Three mountains task?', 'To find out whether children can see a scene from another person\'s point of view', ['To test how well children remember a model after a delay', 'To measure children\'s fear of heights', 'To compare how fast boys and girls learn to count'], 'The task tested egocentrism: whether children understand that another person can see something different from what they see.'));
  dev02.push(mc('findings', 'What did younger children (around 4 to 6) usually choose in the Three mountains task?', 'The picture showing their own view of the mountains', ['The picture showing the doll\'s view', 'A picture chosen at random', 'No picture, because they refused to take part in the task at all'], 'Younger children usually picked their own view, which shows they were egocentric.'));
  dev02.push(mc('findings', 'By about 7 to 9 years, what could most children do in the Three mountains task?', 'Choose the picture showing the doll\'s view', ['Choose only the picture of their own view', 'Describe the mountains but not choose a picture', 'Choose the wrong picture on purpose'], 'By about 7 to 9, most children could choose the doll\'s view, which shows they could decentre (see things from another viewpoint).'));
  dev02.push(mc('conclusion', 'Which conclusion do the findings of the Three mountains task support?', 'Egocentrism belongs to the pre-operational stage and fades as children move on', ['Children are egocentric until they are about 12', 'Egocentrism is only found in the concrete operational stage', 'All children develop the ability to decentre at exactly the same age'], 'Young children chose their own view, while older children could choose the doll\'s. This supports egocentrism being a feature of the pre-operational stage.'));
  dev02.push(mc('key terms', 'What does <b>egocentrism</b> mean in Piaget\'s theory?', 'Being unable to see things from any viewpoint other than your own', ['Being selfish and refusing to share toys or attention with other children', 'Being very confident in your own abilities', 'Believing that objects have feelings'], 'Egocentrism is about thinking, not selfishness: the child cannot take another person\'s perspective.'));
  dev02.push(mc('key terms', 'Piaget described a child who can take another person\'s point of view as being able to do what?', 'Decentre', ['Conserve volume', 'Centre their attention on one feature', 'Use object permanence'], 'Decentring means taking account of more than one viewpoint. It shows the child is moving beyond egocentrism.'));
  dev02.push(mc('application', 'Four-year-old Hana holds a picture book facing herself and asks her grandad to say what animal is on the page. He cannot see it, but she insists he can. Which study\'s finding does this fit best, and why?', 'The Three mountains task, because young children assume others see what they see', ['The Three mountains task, because children aged 4 can always pick the doll\'s view', 'The Three mountains task, because the child has shown she can decentre', 'It does not fit, because the Three mountains task was about memory'], 'Hana behaves like the young children who chose their own view in the study. She cannot yet decentre, so she is egocentric.'));
  dev02.push(mc('application', 'Stella, aged 5, is sitting opposite her mum. Her mum asks, "Which side of the toy farm can I see?" Stella points to the side facing Stella. According to Piaget and Inhelder (1956), which stage is Stella in?', 'Pre-operational, because she shows egocentrism', ['Concrete operational, because she can point to a side', 'Sensorimotor, because she is using toys', 'Formal operational, because she can answer a question'], 'Stella gives her own view instead of her mum\'s, as young children did in the Three mountains task. That is egocentrism, a feature of the pre-operational stage.'));
  dev02.push(mc('application', 'Omar, aged 9, sits at one side of a model village. He works out and shows correctly what a toy figure standing on the opposite side can see. What does this suggest about Omar according to the Three mountains findings?', 'He can decentre and is likely to be in the concrete operational stage', ['He is egocentric and is in the pre-operational stage', 'He is too young to complete a perspective-taking task with a model and doll', 'He is in the sensorimotor stage'], 'By about 7 to 9 years, most children in the study could choose another viewpoint. Omar has decentred, which fits the concrete operational stage.'));
  dev02.push(ms('procedure details', 'Select <b>all</b> the statements that are true about Piaget and Inhelder\'s (1956) Three mountains task.', ['A doll was moved to different positions around the model', 'Children chose from 10 pictures taken from different viewpoints', 'The sample was about 100 children'], ['The model had four mountains', 'Only children under 4 years took part', 'Children explained their choice in writing'], 'The model had three mountains, a doll and 10 pictures, and the sample was 100 children aged about 4 to 12. Children chose a picture; they did not write explanations.'));
  dev02.push(mc('evaluation', 'Which of these is a fair criticism of the Three mountains task?', 'The task is artificial, since children rarely have to picture mountains from different positions in real life', ['The sample was too small to be useful', 'The children were not told it was a study', 'It used only adults'], 'Choosing pictures of a model mountain range is not an everyday task, so it may lack realism. Children may do better on more familiar tasks.'));
  dev02.push(mc('evaluation', 'A critic says young children may have failed the Three mountains task because the task was too difficult to understand rather than because they are egocentric. What is this a criticism of?', 'The validity of the conclusion about egocentrism', ['The ethics of using a doll with such young children', 'The size of the sample', 'The age range used'], 'If children did not understand the instructions or the pictures, their wrong answers might not reflect egocentrism. This questions how valid the conclusion is.'));
  dev02.push({ skill: 'data conclusion', gen: function () {
    var a = rint(14, 18), b = rint(2, 6), tot = 20, cap = pick(['Maya', 'Ibrahim', 'Chloe', 'Tariq']);
    return { kind: 'mcq', q: cap + ' ran a small classroom version of the Three mountains task with 20 children in each age group and counted how many chose the picture of <b>their own view</b>. (These are invented results, not the original findings.)<br>' + table(['Age group', 'Chose own view', 'Chose doll\'s view'], [['4 to 6 years', String(a), String(tot - a)], ['7 to 9 years', String(b), String(tot - b)]]) + 'Which conclusion is best supported by the data?',
      options: ['Younger children are more egocentric: ' + a + ' of 20 aged 4 to 6 chose their own view, compared with ' + b + ' of 20 aged 7 to 9', 'Older children are more egocentric: ' + b + ' of 20 aged 7 to 9 chose their own view', 'Age makes no difference, because some children in both groups chose their own view', 'All of the 7 to 9 year olds had decentred, so egocentrism ends at 7'], answer: 0,
      why: 'Most of the 4 to 6 year olds (' + a + ' of 20) chose their own view, while few of the 7 to 9 year olds (' + b + ' of 20) did. This supports egocentrism being stronger in younger, pre-operational children. A good conclusion quotes the numbers.' };
  } });
  dev02.push({ skill: 'data conclusion', gen: function () {
    var a = rint(15, 19), b = rint(3, 7), who = pick(['Nina', 'Callum', 'Zara']);
    return { kind: 'num', unit: '', answer: a - b, display: String(a - b),
      q: who + ' tested 20 children aged 4 to 6 and 20 children aged 7 to 9 on a Three mountains task. ' + a + ' of the younger children and ' + b + ' of the older children chose the picture of their own view. (These are invented results, not the original findings.)<br>How many <b>more</b> younger than older children chose their own view?',
      why: 'Subtract the older group from the younger group: ' + a + ' &minus; ' + b + ' = ' + (a - b) + '. More younger children chose their own view, which fits egocentrism being common in the pre-operational stage.' };
  } });
  dev02.push(mc('conclusion', 'Which is the best explanation of a conclusion about development from the Three mountains task?', 'Children aged 4 to 6 mostly chose their own view, so they find it hard to see things from another person\'s position', ['Children aged 4 to 6 mostly chose the wrong picture, so they are not clever', 'Children chose from 10 pictures, so the study shows egocentrism', 'The sample was 100 children, so egocentrism ends at 7'], 'A full conclusion states what the children did and what it means about development. Facts about the pictures or sample size are not conclusions about egocentrism.'));
  dev02.push(mc('stage link', 'Which stage of Piaget\'s theory is linked to egocentrism in the Three mountains findings?', 'Pre-operational', ['Sensorimotor', 'Concrete operational', 'Formal operational'], 'Children of about 4 to 6 chose their own view, which Piaget linked to the pre-operational stage. Decentring appears in the concrete operational stage.'));
  B['PSY-DEV-02'] = { title: 'Three mountains task (Piaget and Inhelder, 1956)', items: dev02 };

  /* ---------- PSY-MEM-07 Reductionism and holism ---------- */
  var mem07 = [];
  mem07.push(mc('define reductionism', 'Which statement best defines <b>reductionism</b> in psychology?', 'Explaining complex behaviour by breaking it down into smaller, simpler parts', ['Explaining behaviour by looking at the whole person and their surroundings together', 'Reducing the number of participants in a study to save time', 'Explaining behaviour only by what a person can see and hear'], 'Reductionism breaks a complex behaviour into its simplest components. It is the opposite of studying the whole.'));
  mem07.push(mc('define holism', 'Which statement best defines <b>holism</b> in psychology?', 'Studying behaviour as a whole, because the whole is more than the sum of its parts', ['Studying the smallest possible parts of behaviour one at a time, so that nothing else interferes', 'Studying behaviour in as many different people as possible', 'Studying only the behaviour that can be seen'], 'Holism looks at how the parts work together, as the whole behaviour is more than its separate parts added up.'));
  mem07.push(mc('reductionist example', 'Which explanation of memory is an example of a <b>reductionist</b> approach?', 'The Multi-store Model, which splits memory into sensory register, short-term memory and long-term memory', ['An explanation that combines emotion, culture and schemas to explain how a memory is rebuilt', 'An explanation that says memory depends on the whole person and cannot be divided', 'An explanation that says people remember by storing an exact copy of everything they have seen and heard'], 'The Multi-store Model breaks memory down into separate stores, so it reduces memory to smaller parts. That makes it reductionist.'));
  mem07.push(mc('holistic example', 'Which explanation of memory is an example of a <b>holistic</b> approach?', 'Reconstructive memory, where emotion, culture and schemas interact to affect what is remembered', ['The Multi-store Model, which splits memory into three separate stores', 'An explanation that says memory is just the firing of one set of neurons', 'A count of how many items short-term memory can hold'], 'Reconstructive memory looks at how many factors, such as schemas, emotion and culture, work together to shape recall. That is a holistic view.'));
  mem07.push(mc('difference', 'Which answer correctly describes the <b>difference</b> between reductionism and holism?', 'Reductionism explains behaviour by breaking it into small parts, whereas holism looks at the behaviour as a whole', ['Reductionism looks at the whole behaviour, whereas holism breaks it down into small parts', 'Reductionism is used in experiments, whereas holism is used only in questionnaires', 'Reductionism studies adults, whereas holism studies children'], 'The difference is in the size of the unit of study: small parts for reductionism, the whole and its interacting parts for holism.'));
  mem07.push(mc('evaluation reductionism', 'Which is a <b>strength</b> of a reductionist explanation of memory?', 'Separate parts can be tested scientifically, such as in a controlled lab experiment', ['It gives a complete picture of how emotion and culture affect memory', 'It shows how all of the different parts of memory interact with each other and with emotion', 'It avoids oversimplifying complex behaviour'], 'Breaking behaviour into simple parts makes it easier to measure and test. This is a strength linked to scientific testing.'));
  mem07.push(mc('evaluation reductionism', 'Which is a <b>weakness</b> of a reductionist explanation of memory?', 'It may oversimplify memory by ignoring how factors such as emotion and schemas affect recall', ['It is too difficult to test using experiments', 'It considers too many factors at once to be useful', 'It only applies to the memory of young children'], 'Reductionism can leave out the other factors that influence behaviour, so it may oversimplify. It does not look at the whole.'));
  mem07.push(mc('evaluation holism', 'Which is a <b>strength</b> of a holistic explanation of memory?', 'It gives a more complete picture by considering how different factors work together', ['It breaks memory into parts that are easy to test', 'It is based on well-controlled experiments with simple tasks', 'It avoids any need to consider the person\'s experiences, emotions or cultural background'], 'A holistic view includes the person\'s emotions, culture and schemas. This gives a fuller explanation, although it is harder to test.'));
  mem07.push(mc('evaluation holism', 'Which is a <b>weakness</b> of a holistic explanation of memory?', 'It is harder to test scientifically because so many factors interact', ['It breaks memory into parts and so misses the bigger picture', 'It cannot explain why people forget information that they once knew well', 'It only focuses on one cause of memory'], 'Because holistic explanations include many interacting factors, they are harder to test and control. Reductionist explanations are easier to test.'));
  mem07.push(mc('apply to scenario', 'Dr Okoro studies memory by testing how many words people can recall from a short-term memory store, separately from how many they can recall from a long-term store. Which approach is this?', 'Reductionist, because memory is split into smaller separate parts', ['Holistic, because memory is studied using words', 'Holistic, because two stores are used', 'Reductionist, because only adults take part in the memory tasks used'], 'Dr Okoro treats short-term and long-term memory as separate parts of memory. Breaking memory into simple parts is reductionist.'));
  mem07.push(mc('apply to scenario', 'Dr Park studies why a witness\'s account of an accident changed over time. She looks at the witness\'s mood, past experiences and cultural background and how they combined to alter the memory. Which approach is Dr Park taking?', 'Holistic, because she looks at how several factors interact', ['Reductionist, because she studies only one witness at a time', 'Reductionist, because she looks at mood', 'Holistic, because memory is always accurate'], 'Dr Park looks at the whole picture, with different factors affecting the memory together. That makes her approach holistic.'));
  mem07.push(ms('identify reductionist statements', 'Select <b>all</b> the statements that describe a reductionist approach.', ['Memory is explained by breaking it down into separate stores', 'Complex behaviour is explained by its simplest components', 'A lab task is used to test one part of memory on its own'], ['The whole is more than the sum of its parts', 'Emotion, culture and schemas are all studied as they interact'], 'Reductionist explanations use simple, separate parts. Statements about the whole and interacting factors are holistic.'));
  mem07.push(ms('identify holistic statements', 'Select <b>all</b> the statements that describe a holistic approach.', ['The whole is more than the sum of its parts', 'Different factors that affect memory are studied together', 'Recall is explained as the interaction of schemas and emotion'], ['Memory is split into sensory register, short-term and long-term memory', 'A single part of memory is studied in isolation'], 'Holism looks at the parts working together as a whole. Splitting memory up and studying one part alone are reductionist.'));
  mem07.push(mc('holism wording', 'Which phrase best captures the key idea behind <b>holism</b>?', 'The whole is greater than the sum of its parts', ['The parts matter more than the whole', 'The simplest explanation is always best', 'Behaviour can only be understood by studying the brain'], 'The key holistic idea is that the whole behaviour is more than separate parts added up, because the parts interact.'));
  mem07.push(mc('why MSM is reductionist', 'Why is the Multi-store Model of memory described as <b>reductionist</b>?', 'It reduces memory to three separate stores and does not consider other factors that affect recall', ['It is based on a study of a single person, so its findings cannot be generalised to other people', 'It says memory is a whole that cannot be divided', 'It says memory is affected by culture, emotion and schemas'], 'The model breaks memory down into the sensory register, STM and LTM and leaves out factors such as emotion. This simplifies memory, making it reductionist.'));
  mem07.push(mc('why reconstructive is holistic', 'Why is reconstructive memory described as a <b>holistic</b> explanation?', 'It considers how several factors, such as schemas, culture and emotion, combine to change a memory', ['It breaks memory down into three separate stores', 'It tests one small part of memory in a lab task', 'It explains memory using one factor only'], 'Reconstructive memory looks at how many influences work together on what we recall, which is a holistic view.'));
  mem07.push(mc('definition detail', 'Which answer is the best definition of <b>holism</b>?', 'Looking at how parts of behaviour interact, because the whole is more than the separate parts', ['Looking at everything about a person in great detail, including all of their past experiences', 'Looking at the whole of a person\'s life from birth to death', 'Looking at a large number of people in one study'], 'A good definition includes the idea that parts interact so that the whole is more than the sum of the parts. "Looking at everything" is too vague.'));
  mem07.push(mc('example needed', 'A student is asked to define reductionism and use an example from memory. Which answer would gain <b>full marks</b>?', 'Explaining behaviour by breaking it into simple parts, for example splitting memory into sensory register, STM and LTM', ['Explaining behaviour by breaking it into simple parts', 'Explaining behaviour using a model of memory', 'Explaining memory using stores, which is an example of the Multi-store Model'], 'Full marks need an accurate definition and an example from memory. The other answers give only the definition or only an example.'));
  mem07.push(mc('difference needs both', 'Which answer would earn full credit when asked to describe the difference between reductionism and holism?', 'Reductionism breaks behaviour into small parts, whereas holism looks at the whole behaviour and how its parts interact', ['Reductionism breaks behaviour into small parts, which can oversimplify it', 'Holism looks at the whole behaviour and how its parts interact', 'Reductionism is easy to test, whereas holism is easy to test too'], 'A difference question needs both terms and a clear contrast. Describing only one term does not show the difference.'));
  mem07.push(mc('apply to scenario', 'A researcher says: "Forgetting can be fully explained by the electrical activity of a few neurons." Which approach is the researcher using?', 'Reductionist, because behaviour is explained by one very small part', ['Holistic, because neurons are part of a whole system of the nervous system', 'Holistic, because forgetting is a complex behaviour', 'Neither, because it does not mention memory stores'], 'Explaining a complex behaviour through just one small component is reductionist. A holistic explanation would include more factors.'));
  mem07.push(mc('evaluation reductionism', 'Which statement is a reasonable criticism of explaining memory using only the Multi-store Model?', 'It does not explain how emotions or past experience can change what we remember', ['It looks at too many factors at the same time to be of any use in a lab experiment', 'It cannot be tested because memory cannot be broken into parts', 'It explains memory only in people with brain damage'], 'The Multi-store Model reduces memory to stores, so it leaves out other influences. This oversimplification is the main reductionist criticism.'));
  mem07.push(mc('evaluation holism', 'Daniel says: "Holistic explanations of memory are better because they are always easier to test." Why is Daniel wrong?', 'Holistic explanations include many interacting factors, which makes them harder to test', ['Holistic explanations cannot be applied to memory', 'Holistic explanations use only one factor, which makes them too simple and very easy to test', 'Holistic explanations have been proven wrong by experiments'], 'A strength of holism is its completeness, but a weakness is that many interacting factors are hard to isolate and test.'));
  mem07.push(mc('compare approaches', 'A psychology teacher says a lab study of short-term memory with word lists is reductionist but gives clear, testable results. Which statement best explains why it is reductionist?', 'It studies one small part of memory in isolation rather than the whole of memory', ['It uses a large number of participants to test the whole of human memory at the same time', 'It looks at how culture changes recall', 'It involves recording what people say'], 'Studying one small part of memory alone is reductionist. The controlled task makes the part easy to test.'));
  B['PSY-MEM-07'] = { title: 'Reductionism and holism', items: mem07 };

  /* ---------- PSY-PRB-01 Symptoms of depression and addiction, and their impact ---------- */
  var prb01 = [];
  prb01.push(mc('depression symptoms', 'According to the ICD, which of these is a symptom of depression?', 'Feeling low or losing interest in things for most of the day, nearly every day, for at least two weeks', ['Needing more of a substance to get the same effect', 'Being unable to stop using something despite wanting to', 'Feeling extremely excited and full of energy for several days'], 'Persistent low mood or loss of interest and pleasure, lasting at least two weeks, is the central symptom of depression. Needing more of a substance (tolerance) is a feature of addiction.'));
  prb01.push(mc('depression symptoms', 'Which of these is a recognised symptom of depression?', 'Feelings of worthlessness or guilt', ['Withdrawal symptoms when stopping something', 'Carrying on using something despite the harm it causes', 'Using something more and more to get the same effect'], 'Worthlessness and guilt are ICD symptoms of depression. The other options are features of addiction.'));
  prb01.push(ms('depression symptoms', 'Select <b>all</b> the symptoms that can be part of depression according to the ICD.', ['Tiredness and low energy', 'Poor concentration', 'Changes in sleep or appetite'], ['Tolerance of a substance', 'Withdrawal symptoms when use stops'], 'Tiredness, poor concentration and changes in sleep or appetite are depression symptoms. Tolerance and withdrawal are features of addiction.'));
  prb01.push(mc('depression duration', 'How long must low mood or loss of interest last, according to the ICD, to be a symptom of depression?', 'At least two weeks', ['At least two days', 'At least six months', 'One hour each day'], 'Symptoms must be present most of the day, nearly every day, for at least two weeks.'));
  prb01.push(mc('addiction features', 'According to the ICD, which of these is a feature of addiction?', 'Impaired control over how much, when or whether to use', ['Feelings of worthlessness or guilt', 'Waking very early in the morning', 'Hopelessness about the future'], 'Impaired control over starting, amount and stopping use is a key feature of addiction (dependence). The other options are depression symptoms.'));
  prb01.push(ms('addiction features', 'Select <b>all</b> the features of addiction.', ['Tolerance', 'Withdrawal symptoms when use stops', 'Carrying on despite harm'], ['Loss of interest in everything for two weeks', 'Hopelessness about the future'], 'Tolerance, withdrawal and continued use despite harm are features of addiction. Loss of interest and hopelessness are depression symptoms.'));
  prb01.push(mc('addiction features', 'Ben finds that he now needs to play online games for six hours to get the same excitement that two hours gave him a year ago. Which feature of addiction is this?', 'Tolerance', ['Withdrawal', 'Loss of control over stopping', 'A symptom of depression'], 'Tolerance means needing more of an activity or substance to get the same effect, which is what Ben describes.'));
  prb01.push(mc('addiction features', 'When Anya stops smoking for a day, she becomes shaky, irritable and cannot sleep. Which feature of addiction does this show?', 'Withdrawal symptoms', ['Tolerance', 'Low mood lasting two weeks', 'Hopelessness about the future'], 'Unpleasant physical or mental symptoms that appear when use stops are withdrawal symptoms.'));
  prb01.push(mc('addiction features', 'Callum knows that drinking is making him ill and costing him his job, but he keeps drinking. Which feature of addiction is this?', 'Carrying on despite harm', ['Tolerance', 'Hopelessness about the future', 'A change in appetite'], 'Continuing to use even though it is causing harm is one of the ICD features of addiction.'));
  prb01.push(mc('addiction features', 'Rhea spends all her free time and money on gambling, and no longer goes to her swimming club or sees friends. Which ICD feature of addiction is she showing?', 'Use becoming more important than other activities and duties', ['Tiredness and low energy', 'Thoughts of death', 'Poor concentration at school'], 'Addiction involves the behaviour taking priority over other activities and responsibilities, as shown here by gambling replacing swimming and friends.'));
  prb01.push(mc('apply to scenario', 'For the past month, Priya has felt sad and empty almost every day. She has stopped enjoying her hobbies, sleeps badly and feels she is a burden to her family. What does she show?', 'Symptoms of depression', ['Features of addiction', 'Withdrawal symptoms', 'Tolerance'], 'Persistent low mood, loss of interest, poor sleep and worthlessness are depression symptoms. There is no substance or behaviour that she cannot control.'));
  prb01.push(mc('apply to scenario', 'Max drinks every day and says he cannot cut down even though he has tried. He now needs far more drink than before to feel the same effect. Which description fits Max best?', 'Features of addiction', ['Symptoms of depression', 'Normal social drinking', 'A problem with concentration only'], 'Trying but failing to cut down shows impaired control, and needing more for the same effect is tolerance. Both are features of addiction.'));
  prb01.push(mc('symptom not cause', 'Which answer states a <b>symptom</b> of depression rather than a cause?', 'Poor concentration', ['A family history of depression', 'Losing a job', 'Low levels of serotonin'], 'A symptom is something the person experiences, such as poor concentration. Family history, life events and chemicals are possible causes.'));
  prb01.push(mc('symptom not cause', 'Which of these is a <b>feature</b> of addiction rather than a cause of it?', 'Withdrawal symptoms when use stops', ['Peer pressure to try something', 'Growing up with a parent who drinks', 'Stress at work'], 'Withdrawal is something that happens as part of addiction. The others are possible reasons a person might start or continue to use.'));
  prb01.push(mc('effects on individuals', 'Which of these is an effect of depression or addiction on an <b>individual</b>?', 'Problems keeping up with school or work and difficulties in relationships', ['A rise in the cost of running the health service', 'Fewer working days for the whole country', 'More pressure on local police forces'], 'Effects on individuals are personal: work or school, relationships, health, money and self-care. The other options are effects on society.'));
  prb01.push(mc('effects on society', 'Which of these is an effect of mental health problems on <b>society</b>?', 'The cost of treatment to health services', ['A person losing touch with friends', 'A person feeling worthless', 'A person sleeping badly'], 'Costs to health services affect many people in society. The other options affect just the individual.'));
  prb01.push(mc('effects on society', 'Many people take time off work because of depression or addiction. Which is an effect on <b>society</b>?', 'Lost working days and lower productivity', ['The person\'s own savings falling', 'The person having less energy to cook', 'The person\'s mood getting worse'], 'Lost working days and lower productivity affect businesses and the economy, so this is an effect on society.'));
  prb01.push(mc('effects on society', 'Which is a possible effect of addiction on society, as well as on the individual?', 'Addiction may be linked to crime', ['The person has unusual dreams', 'The person feels worthless', 'The person finds it hard to concentrate'], 'Addiction can be linked to crime, such as stealing to pay for drugs, which affects society and not just the addict.'));
  prb01.push(mc('effects on individuals', 'Jordan has become addicted to gaming and is failing his course. His money is also running out because he spends it on in-game items. Which statement correctly describes effects on Jordan as an <b>individual</b>?', 'It is affecting his studies and his finances', ['It is increasing the cost of health services', 'It is reducing national productivity', 'It is changing the laws of his society'], 'Failing his course and running out of money are personal effects. National costs and productivity are effects on society.'));
  prb01.push(mc('incidence', 'Which of the following is a reason why the number of <b>diagnosed</b> cases of mental health problems has risen over time?', 'Greater awareness and less stigma, so more people seek help and are diagnosed', ['Doctors have stopped using the ICD', 'Mental health problems were unknown before', 'People no longer face any stress'], 'Better awareness, less stigma and more diagnosis explain part of the rise. Changes in life stress may also contribute.'));
  prb01.push(mc('two distinct symptoms', 'A student is asked to state <b>two</b> symptoms of depression. Which answer would earn both marks?', 'Hopelessness about the future and poor concentration', ['Feeling sad and feeling unhappy', 'Low mood and low mood most days', 'Hopelessness and a family history of depression'], 'Two marks need two different symptoms. Sad and unhappy are the same idea, and a family history is a cause not a symptom.'));
  prb01.push(mc('two distinct features', 'A student is asked to state <b>two</b> features of addiction. Which answer would earn both marks?', 'Tolerance and withdrawal symptoms', ['Withdrawal and feeling ill when stopping', 'Loss of control and being unable to control use', 'Tolerance and feeling worthless'], 'Two marks need two different features. Withdrawal and "feeling ill when stopping" are one idea, and feeling worthless is a depression symptom.'));
  prb01.push(mc('abbreviation', 'What does ICD stand for?', 'International Classification of Diseases', ['Intelligence and Cognitive Development', 'International Council of Doctors', 'Illness and Common Disorders'], 'The ICD is the International Classification of Diseases, which lists the symptoms used to diagnose conditions.'));
  prb01.push(mc('effects on individuals', 'Which is an effect of depression that may be seen in a person\'s <b>physical health or self-care</b>?', 'Changes in sleep and appetite', ['Higher taxes to pay for treatment', 'Fewer people in work', 'More crime in the local area'], 'Sleep and appetite changes affect the individual\'s own body and self-care. Taxes, jobs and crime are effects on society.'));
  prb01.push(mc('apply to scenario', 'Mrs Hall looks after her husband, who has an addiction, and has had to give up her part-time job. Which effect of a mental health problem is this?', 'Pressure on families and carers', ['Increased cost of treatment for the health service', 'Tolerance', 'Loss of interest in activities'], 'Families and carers may have to give up work or time to support someone with a mental health problem. This is an effect beyond the individual.'));
  B['PSY-PRB-01'] = { title: 'Symptoms of depression and addiction, and their impact', items: prb01 };

  /* ---------- PSY-PRB-05 CBT as a treatment for depression and addiction ---------- */
  var prb05 = [];
  prb05.push(mc('what CBT is', 'What is cognitive behavioural therapy (CBT)?', 'A talking therapy that changes negative or irrational thoughts and the behaviours linked to them', ['A drug treatment that changes the level of chemicals in the brain to improve mood and behaviour', 'A therapy that uncovers childhood memories to explain current problems', 'A treatment that rewards a person each time they avoid a trigger'], 'CBT is a talking therapy. It aims to change unhelpful thinking and behaviour, not to prescribe drugs.'));
  prb05.push(mc('technique', 'Which technique is part of CBT for depression?', 'Challenging irrational thoughts by testing them against evidence', ['Taking medication that blocks the reuptake of serotonin in the synapse', 'Replacing a drug with a safer substitute', 'Making the person feel sick when they drink'], 'In CBT, the therapist and client identify irrational thoughts and test them against evidence to replace them with more rational ones.'));
  prb05.push(mc('technique', 'Between sessions, a CBT therapist asks a client to write down upsetting thoughts and what happened just before each one. What is this technique called?', 'Keeping a thought diary as homework', ['A dream diary for the therapist to interpret', 'A diary of the side effects of drugs', 'A weekly list of what the therapist said'], 'Homework tasks such as a thought diary help the client notice and challenge their thoughts between sessions.'));
  prb05.push(mc('technique', 'How does CBT help someone with an addiction to avoid relapse?', 'It helps them identify triggers, manage cravings and build coping strategies', ['It gives them a drug that prevents any cravings', 'It makes them forget the reasons why they started using in the first place', 'It removes the need for them to attend any sessions'], 'For addiction, CBT works on triggers, cravings and coping strategies to prevent relapse.'));
  prb05.push(mc('apply depression', 'Hamid, who is depressed, often thinks: "Because I failed one test, I will fail at everything." How might a CBT therapist help?', 'By helping him test this thought against evidence and replace it with a more realistic one', ['By prescribing a drug to stop the thought happening and to change his brain chemistry over time', 'By asking him to say the thought out loud many times', 'By telling him to ignore all his thoughts'], 'A CBT therapist would help Hamid challenge the irrational thought (for example listing times he has succeeded) and replace it with a more rational one.'));
  prb05.push(mc('apply addiction', 'Cleo plays online card games for hours and feels strong cravings when she gets bored in the evening. Which CBT approach could help her?', 'Identifying that boredom is a trigger and planning a coping strategy, such as going for a walk', ['Taking a drug that makes her ill when she plays', 'Prescribing a substitute that reduces her cravings', 'Telling her to stop and not discussing it further'], 'CBT would help Cleo recognise boredom as a trigger and practise a different behaviour when cravings arise.'));
  prb05.push(mc('apply depression', 'Joel\'s therapist asks him to do a task between sessions: each day he must write down one thing he did well and test whether his thought "I am useless" was true. How does this help Joel with depression?', 'It lets him practise new ways of thinking and collect evidence against his negative thoughts', ['It treats his depression by changing his brain chemistry', 'It stops him thinking about his problems at all for a while, so that he feels calmer and can rest', 'It helps him forget what happened in the past'], 'Homework lets the client practise challenging negative thoughts in daily life, which helps the new thinking last.'));
  prb05.push(mc('not CBT', 'Which of the following is <b>not</b> part of CBT?', 'Prescribing a drug to alter brain chemicals', ['Setting homework between sessions', 'Challenging irrational thoughts', 'Planning ways to cope with cravings and triggers'], 'CBT is a talking therapy, so it does not involve prescribing drugs. Drug treatment is a separate treatment.'));
  prb05.push(mc('strength', 'Which is a <b>strength</b> of CBT for depression and addiction?', 'It tackles the thinking behind the problem, and there are no drug side effects', ['It works quickly with no effort needed from the client, and it suits every type of problem', 'It deals with the biological causes of the problem', 'It is suitable for everyone, whatever their motivation'], 'CBT targets thinking and behaviour and avoids the side effects of drugs. It does need effort and does not treat biological causes.'));
  prb05.push(mc('strength', 'Which is a <b>strength</b> of CBT compared with taking a drug?', 'The skills learned can last after the therapy ends', ['The effects begin after the very first session', 'It is easier for the client because they only have to attend', 'It always works better for severe depression'], 'Clients keep the skills they learn, such as challenging thoughts, so benefits may last. Drugs can lead to relapse when stopped.'));
  prb05.push(mc('strength', 'CBT has been tested in research, such as Young (2007) with internet addiction. How does this research support CBT?', 'It gives evidence that CBT can work as a treatment', ['It shows that CBT has no side effects', 'It proves that thoughts are the only cause of addiction', 'It shows drugs are better than talking therapies'], 'Research that shows people improving after CBT supports it as a treatment. It does not show that thoughts are the only cause or that other treatments are worse.'));
  prb05.push(mc('weakness', 'Which is a <b>weakness</b> of CBT?', 'The client needs to be motivated and accept that they have a problem', ['It has harmful side effects, like nausea', 'It works only when a person takes it for life', 'It cannot be used with anyone who has depression, because it only works for addiction'], 'CBT relies on active effort, such as homework, so it works best for clients who are willing to take part.'));
  prb05.push(mc('weakness', 'Which is a <b>weakness</b> of using CBT to treat depression?', 'It may be less suitable for severe depression, when the person finds it hard to concentrate on therapy', ['It causes side effects such as sleep problems', 'It only treats the physical symptoms of depression', 'It makes the person depend on the therapist\'s drugs'], 'Severe depression can reduce energy and concentration, which can make CBT difficult. It does not cause drug side effects.'));
  prb05.push(mc('weakness', 'Which is a <b>weakness</b> of CBT linked to causes of mental health problems?', 'It ignores biological causes, such as differences in brain chemistry', ['It ignores the person\'s thoughts and behaviour', 'It only helps people whose problem is caused by drugs rather than by their thinking', 'It takes away the person\'s control over their treatment'], 'CBT focuses on thinking and behaviour, so if part of the problem is biological, it may not deal with it.'));
  prb05.push(mc('weakness', 'A client complains that CBT is not a quick fix. Which weakness of CBT does this show?', 'It takes time and effort over many sessions before it works', ['It makes a person sick if they use a substance', 'It cannot be used with children', 'It has to be taken every day to stop relapse'], 'CBT is not a quick fix: the client needs to attend sessions and do homework over time.'));
  prb05.push(mc('apply weakness', 'Freya has addiction problems but says she does not think she has a problem and only came because her parents insisted. Why might CBT be less effective for Freya?', 'CBT needs her to be motivated and to accept that she has a problem', ['CBT would give her unwanted side effects', 'CBT only works for depression, so it could not help with her addiction at all', 'CBT would make her tolerance worse'], 'Because CBT relies on the client\'s effort and agreement, a person who does not accept that they have a problem may not benefit.'));
  prb05.push(mc('apply strength', 'Idris has depression but does not want to take medication because of the side effects. Why might CBT be suitable for him?', 'It is a talking therapy, so there are no drug side effects', ['It changes brain chemicals more quickly than drugs', 'It means he will not need to do any work himself between the therapy sessions', 'It treats the biological cause of depression'], 'A strength of CBT is that it does not use drugs, so it avoids side effects.'));
  prb05.push(mc('best explanation', 'Which answer is the best explanation of how CBT could help Ella, who has depression and often thinks "nobody likes me"?', 'The therapist helps Ella test her thought against evidence, such as friends who invite her out, so she replaces it with a more rational one', ['The therapist talks to Ella about her problems so she feels better', 'CBT is a talking therapy that can help depression', 'The therapist gives Ella tablets to change how she thinks'], 'A full answer names a CBT technique (challenging irrational thoughts) and applies it to Ella\'s thought. Vague "talking about problems" does not earn credit.'));
  prb05.push(mc('best explanation', 'Which is the best explanation of how CBT could help Gareth, who is addicted to gambling and gets strong cravings after payday?', 'The therapist helps him spot payday as a trigger and plan coping strategies, such as meeting a friend instead', ['The therapist tells Gareth to stop gambling, and he will feel better', 'CBT helps to treat addiction by helping people', 'The therapist gives him a drug that makes him feel ill when he gambles'], 'A good answer names a CBT technique (identifying triggers and building coping strategies) and ties it to Gareth\'s payday cravings.'));
  prb05.push(ms('techniques', 'Select <b>all</b> the things a CBT therapist might do.', ['Help the client identify irrational thoughts', 'Set homework such as a thought diary', 'Help the client plan how to cope with cravings'], ['Prescribe a drug that blocks serotonin reuptake', 'Give a substitute drug to reduce withdrawal'], 'CBT uses talking, identifying and challenging thoughts, homework and coping plans. Drug prescribing belongs to drug treatments.'));
  prb05.push(ms('weaknesses of CBT', 'Select <b>all</b> the weaknesses of CBT.', ['It needs motivation from the client', 'It can take a long time and a lot of effort', 'It ignores biological causes'], ['It causes drug side effects', 'It cannot teach any lasting skills'], 'Motivation, time and ignoring biology are weaknesses of CBT. It has no drug side effects, and its skills can last.'));
  prb05.push(mc('irrational thoughts', 'Which is an example of an <b>irrational thought</b> that CBT would challenge?', '"If I make one mistake, everyone will think I am a failure."', ['"I made a mistake today, so I will check my work next time."', '"I feel tired, so I will go to bed early."', '"I disagree with my friend, but we can still talk."'], 'Irrational thoughts are exaggerated or untrue and can be tested against evidence. The other thoughts are realistic.'));
  prb05.push(mc('compare treatments', 'Which statement correctly compares CBT with drug treatment?', 'CBT works on thoughts and behaviour, whereas drugs act on the brain or body', ['CBT acts on brain chemicals, whereas drugs change thoughts', 'CBT always works much faster than drugs and is never affected by the client\'s motivation', 'Both treat the biological cause of the problem'], 'CBT is a talking therapy that changes thinking and behaviour. Drug treatments change chemicals in the brain or body.'));
  prb05.push(mc('technique detail', 'In CBT, what is the purpose of challenging an irrational thought?', 'To replace it with a more rational one', ['To help the client forget the thought completely', 'To prove the therapist is right', 'To make the client stop feeling any emotion'], 'The therapist and client test the thought against evidence so that it can be replaced with a more rational one.'));
  B['PSY-PRB-05'] = { title: 'CBT as a treatment for depression and addiction', items: prb05 };

  /* ---------- PSY-PRB-07 Drug treatments for depression and addiction ---------- */
  var prb07 = [];
  prb07.push(mc('how SSRIs work', 'How do SSRIs (selective serotonin reuptake inhibitors) such as fluoxetine treat depression?', 'They block the reuptake of serotonin, so more serotonin stays in the synapse', ['They add extra serotonin directly into the brain from outside', 'They destroy serotonin so that it cannot cause low mood', 'They stop neurons making serotonin'], 'SSRIs stop serotonin being taken back up by the sending neuron, so more of it stays in the synapse to stimulate the receiving neurons.'));
  prb07.push(mc('how SSRIs work', 'After an SSRI is taken, what happens at the synapse?', 'The sending neuron takes up less serotonin, so more remains to stimulate the receiving neuron', ['The receiving neuron stops responding to serotonin', 'The sending neuron releases less serotonin', 'Serotonin is broken down faster in the synapse'], 'The drug blocks the reuptake of serotonin, so there is more in the synapse for the receiving neuron to detect.'));
  prb07.push(mc('common error', 'Which sentence about SSRIs is <b>most accurate</b>?', 'They work by stopping serotonin being reabsorbed', ['They work by adding serotonin to the brain', 'They work by replacing serotonin with another chemical', 'They work by removing serotonin from the synapse'], 'A common error is to say that SSRIs add serotonin. They block its reuptake so that the existing serotonin stays active for longer.'));
  prb07.push(mc('depression drugs', 'Which drug would a doctor most likely prescribe for depression?', 'Fluoxetine, an SSRI', ['Methadone', 'Disulfiram', 'Nicotine replacement patches'], 'Fluoxetine is an SSRI used for depression. Methadone, disulfiram and nicotine replacement are used for addiction.'));
  prb07.push(mc('addiction drugs', 'How does methadone help a person who is addicted to heroin?', 'It replaces heroin and reduces withdrawal symptoms', ['It makes the person sick if they take heroin', 'It blocks the reuptake of serotonin', 'It teaches the person to avoid places that trigger their use'], 'Methadone is a substitute for heroin that reduces withdrawal symptoms while the person cuts down.'));
  prb07.push(mc('addiction drugs', 'How does disulfiram (Antabuse) help someone with alcohol addiction?', 'It makes the person feel sick if they drink alcohol', ['It replaces alcohol with a similar substance', 'It blocks the reuptake of serotonin', 'It reduces cravings for nicotine when a person stops smoking'], 'Disulfiram causes unpleasant effects such as sickness if alcohol is drunk, so the person associates drinking with feeling ill.'));
  prb07.push(mc('addiction drugs', 'What do nicotine replacement products, such as patches, do?', 'They give a person a small amount of nicotine to reduce cravings when stopping smoking', ['They make the person ill if they smoke', 'They block serotonin reuptake', 'They teach the person coping strategies'], 'Nicotine replacement reduces cravings and withdrawal while the person stops smoking.'));
  prb07.push(mc('match drug to problem', 'Which drug-and-problem pairing is correct?', 'Disulfiram for alcohol addiction', ['Fluoxetine for heroin addiction', 'Methadone for depression', 'Nicotine patches for alcohol addiction'], 'Disulfiram is used for alcohol addiction, fluoxetine for depression, methadone for heroin and nicotine replacement for smoking.'));
  prb07.push(mc('match drug to problem', 'A doctor wants to help a patient with heroin addiction through withdrawal. Which drug is most suitable?', 'Methadone', ['Fluoxetine', 'Disulfiram', 'An SSRI'], 'Methadone replaces heroin and reduces withdrawal. Fluoxetine and other SSRIs are for depression, and disulfiram is for alcohol.'));
  prb07.push(mc('strength', 'Which is a <b>strength</b> of using drugs to treat depression?', 'Symptoms can be reduced enough for other therapy to start', ['They treat the cause of the depression, such as stress', 'They have no side effects', 'The person can stop taking them at once without any risk of relapse'], 'Drugs can reduce symptoms so that a person feels well enough to start other therapy. They treat symptoms, not causes, and often have side effects.'));
  prb07.push(mc('strength', 'Which is a <b>strength</b> of drug treatments?', 'They are easy to take, for example as a tablet or patch', ['They teach the person new ways of thinking that last after treatment ends', 'They treat the cause of the problem, not the symptoms', 'They have no risk if the person stops taking them'], 'Drugs are easy to use and need little effort from the patient, which is a practical strength.'));
  prb07.push(mc('strength', 'Drug trials often show that a medication reduces symptoms more than a placebo. How does this affect the evaluation of drug treatment?', 'It gives research support for drugs as a treatment', ['It shows drugs treat the cause of the problem', 'It proves that drugs have no side effects', 'It shows that therapy is not needed by anyone with this problem'], 'Trial evidence that symptoms reduce is research support, which is a strength. It does not show that drugs treat the cause or are free from side effects.'));
  prb07.push(mc('weakness', 'Which is a <b>weakness</b> of drug treatment?', 'They may cause side effects, for example nausea or sleep problems', ['They can only be given by a trained therapist in person', 'They change the person\'s thinking and behaviour for good', 'They work only if the person has strong motivation'], 'Side effects such as nausea and sleep problems are a weakness of drugs such as SSRIs.'));
  prb07.push(mc('weakness', 'Why might a person on antidepressants relapse after stopping the tablets?', 'The drug treats symptoms, not the cause, so the symptoms can return', ['The drug caused the depression in the first place', 'The person has already learned to cope without help during the treatment', 'The drug changed the cause of the depression for good'], 'Drugs often only treat symptoms, so if the person stops taking them and the cause remains, the symptoms can return.'));
  prb07.push(mc('weakness', 'Why can methadone be a weakness as a treatment for heroin addiction?', 'It can itself be addictive, so the person may swap one addiction for another', ['It makes the person sick if they drink alcohol', 'It has no effect on withdrawal', 'It cannot be taken as a tablet or liquid'], 'Substitutes such as methadone can themselves be addictive, which is a weakness of this treatment.'));
  prb07.push(mc('weakness', 'Which is a <b>weakness</b> of using SSRIs?', 'They usually take a few weeks to work', ['They are effective on the first day', 'They remove the stress that caused the depression', 'They are only used when a person is motivated'], 'SSRIs often take weeks before the effects are noticed, so the person may suffer for a time and may give up too soon.'));
  prb07.push(mc('apply to scenario', 'Mo has been told to take fluoxetine for his depression. He asks how it will help. Which is the best explanation?', 'It stops serotonin being reabsorbed, so more is available to stimulate neurons and lift his mood', ['It adds new serotonin to his brain so his mood improves', 'It works as a talking therapy to change how he thinks', 'It will make him sick if he feels low'], 'An SSRI blocks reuptake so that serotonin stays in the synapse. This links the drug action to the aim of reducing his symptoms.'));
  prb07.push(mc('apply to scenario', 'Kayla has tried many times to quit drinking but still craves alcohol, and her doctor prescribes disulfiram. Why might this help?', 'Drinking would make her feel sick, so she may be put off drinking', ['It will replace the alcohol and reduce withdrawal', 'It will block serotonin reuptake to lift her mood', 'It will remove the stress that makes her drink and teach her to cope without it'], 'Disulfiram causes sickness if alcohol is drunk, so it discourages Kayla from drinking.'));
  prb07.push(mc('apply to scenario', 'Isaac is addicted to heroin and has severe withdrawal symptoms whenever he stops. Which drug action would help most?', 'A substitute that replaces heroin and reduces withdrawal', ['A drug that makes him sick when he uses heroin', 'A drug that blocks the reuptake of serotonin in the synapse', 'A drug that stops him having any thoughts about heroin'], 'Methadone replaces heroin and reduces withdrawal symptoms, so it is suitable for Isaac.'));
  prb07.push(mc('apply weakness', 'Lucia takes tablets for depression and has stopped sleeping well. She is considering stopping them. Which weakness of drug treatment does this show?', 'Side effects, such as sleep problems, which may lead her to stop', ['The drugs can be easily replaced by therapy, which has no side effects', 'The drugs work only if she stays motivated', 'The drugs treat the cause of her depression'], 'Sleep problems are a side effect of SSRIs. A weakness is that side effects may lead people to stop taking their treatment.'));
  prb07.push(mc('best explanation', 'Which is the best explanation of <b>one weakness</b> of drugs for Daniel, who is addicted to heroin and is prescribed methadone?', 'Methadone can itself be addictive, so Daniel could become dependent on it instead of heroin', ['Methadone is a drug, so it is a weakness', 'Methadone is not as good as a talking therapy', 'Daniel may find methadone hard to take'], 'A full weakness names the problem (methadone can be addictive) and links it to the person (Daniel may swap heroin dependence for methadone dependence).'));
  prb07.push(mc('two different weaknesses', 'A student is asked for <b>two different weaknesses</b> of drug treatment for addiction. Which answer gives two separate points?', 'Side effects, and the person may relapse when they stop taking the drug', ['Side effects, and the drug makes the person ill', 'Relapse, and the addiction coming back after stopping', 'The drug is addictive, and the person depends on it'], 'Two weaknesses must be different. "Makes the person ill" repeats side effects; relapse and the addiction coming back are the same idea; addictive and dependent are the same idea.'));
  prb07.push(ms('drug actions', 'Select <b>all</b> the statements that correctly describe how drug treatments work.', ['SSRIs block the reuptake of serotonin', 'Methadone replaces heroin to reduce withdrawal', 'Disulfiram makes a person sick if they drink alcohol'], ['SSRIs add extra serotonin from outside the body', 'Nicotine replacement makes a person sick if they smoke'], 'SSRIs block reuptake, methadone substitutes for heroin, and disulfiram punishes drinking. Nicotine replacement reduces cravings and does not make people ill.'));
  prb07.push(ms('weaknesses of drugs', 'Select <b>all</b> the weaknesses of drug treatments.', ['Side effects', 'Relapse if the person stops taking them', 'They treat symptoms, not the cause'], ['They teach long-lasting coping skills', 'They need no effort from the patient'], 'Side effects, relapse and treating only symptoms are weaknesses. Teaching skills is a strength of CBT, and needing no effort is a strength of drugs.'));
  prb07.push(mc('describe action', 'A student is asked to describe how drugs could treat depression. Which answer gives the action step by step?', 'An SSRI blocks serotonin from being reabsorbed, so more stays in the synapse and stimulates neurons, which helps lift mood', ['An antidepressant is a tablet that people take every day for depression', 'A doctor prescribes a drug that helps with the symptoms', 'Serotonin is a chemical that is linked to mood in the brain'], 'A full description names the drug, says what it does to the neurotransmitter (blocks reuptake) and explains why that helps mood.'));
  B['PSY-PRB-07'] = { title: 'Drug treatments for depression and addiction', items: prb07 };

  /* ---------- PSY-SOC-07 Culture and society ---------- */
  var soc07 = [];
  soc07.push(mc('define society', 'Which is the best definition of <b>society</b>?', 'A large group of people who live in the same area and share rules, laws and norms of behaviour', ['The shared beliefs, customs and traditions passed down across generations', 'A small group of friends who share the same interests', 'A group of people who work for the same company and follow its rules, policies and codes of conduct'], 'Society is a large group living in the same area under shared rules and laws. The second option describes culture.'));
  soc07.push(mc('define culture', 'Which is the best definition of <b>culture</b>?', 'The shared beliefs, values, customs and traditions of a group of people, passed on across generations', ['A large group of people who live in the same area and follow the same laws', 'A problem that affects many people in a society', 'The way a single person chooses to behave when they are alone and are not influenced by any other people'], 'Culture is about the shared beliefs, values and customs of a group. The first option describes a society.'));
  soc07.push(mc('define social issue', 'Which is the best definition of a <b>social issue</b>?', 'A problem that affects many people in a society', ['A disagreement between two friends', 'A custom passed on in one family', 'A rule that every person in the world must follow'], 'A social issue is a problem affecting many people in a society, such as crime, prejudice or mental health problems.'));
  soc07.push(mc('social issue example', 'Which of these is an example of a <b>social issue</b>?', 'Prejudice against a group of people', ['A person choosing a favourite colour', 'A student forgetting their homework once', 'A family deciding where to go on holiday'], 'Prejudice affects many people in a society so it is a social issue. The other options are individual or private matters.'));
  soc07.push(mc('society vs culture', 'Which statement correctly shows the <b>difference</b> between society and culture?', 'Society is the group of people, whereas culture is their shared beliefs, values and customs', ['Society is the shared beliefs of a group, whereas culture is the laws they follow', 'Society and culture mean exactly the same thing', 'Society is only found in cities, whereas culture is only found in villages'], 'A society is the group living together under shared rules and laws; culture is the set of shared beliefs, values and customs of a group.'));
  soc07.push(mc('individualist', 'Which statement describes an <b>individualist</b> culture?', 'It values independence and personal goals', ['It values group harmony and duty to the group', 'It values obedience to elders above everything', 'It has no rules or laws'], 'Individualist cultures, such as the USA and UK, stress independence and personal goals.'));
  soc07.push(mc('collectivist', 'Which statement describes a <b>collectivist</b> culture?', 'It values group harmony and duty to the group', ['It values independence and personal goals most', 'It has no shared customs', 'It values competition between individuals'], 'Collectivist cultures, such as China and Japan, stress group harmony and duty.'));
  soc07.push(mc('examples of cultures', 'Which pair of countries contains <b>one</b> typically individualist culture and <b>one</b> typically collectivist culture?', 'The USA and China', ['China and Japan', 'The USA and the UK'], 'The USA and UK are individualist, while China and Japan are collectivist. Only the USA and China give one of each.'));
  soc07.push(mc('Bond and Smith', 'According to Bond and Smith (1996), which people tend to conform <b>more</b>?', 'People from collectivist cultures', ['People from individualist cultures', 'People from every culture conform equally', 'Only young adults in individualist cultures'], 'Bond and Smith found that conformity tends to be higher in collectivist cultures, where group harmony is valued.'));
  soc07.push(mc('apply conformity', 'In Tomo\'s school, students are taught to keep group harmony and avoid standing out. Based on research on culture and conformity, what would you expect?', 'Higher conformity than in an individualist culture, as shown by Bond and Smith (1996)', ['Lower conformity, because students value independence', 'No effect, because culture does not affect conformity', 'Higher conformity, because collectivist cultures reject group norms'], 'Valuing group harmony is typical of collectivist cultures, where conformity tends to be higher.'));
  soc07.push(mc('apply conformity', 'Everyone in Kasia\'s class is encouraged to pursue their own goals and to speak up when they disagree. Which type of culture does her class most likely have?', 'Individualist, because independence is valued', ['Collectivist, because the class speaks up', 'Collectivist, because the class has goals', 'Neither, because culture is not about values or beliefs'], 'Valuing independence and personal goals is a feature of an individualist culture.'));
  soc07.push(mc('generalising research', 'Much research on social influence was carried out in the USA. What problem does this cause?', 'The findings may not apply to people in other cultures', ['The research cannot be repeated', 'The research is unethical', 'The samples are always too small to use'], 'People in other cultures may behave differently, for example conforming more in collectivist cultures, so findings from the USA may not generalise.'));
  soc07.push(mc('describe influence', 'Which answer best describes <b>one way culture could influence behaviour</b> in psychology?', 'People in collectivist cultures tend to conform more because they value group harmony', ['People are born with a fixed culture, so they behave the same wherever they live', 'Culture only affects what clothes people wear', 'People in cultures with laws conform more than others'], 'A full answer names an influence (higher conformity) and develops it using the collectivist value of group harmony.'));
  soc07.push(mc('culture across generations', 'Which feature shows that something is part of a <b>culture</b> rather than just one person\'s habit?', 'It is shared by a group and handed down from one generation to the next', ['It is chosen by one person and not shared', 'It only exists for a few days', 'It is written in the law'], 'Culture is shared and passed on across generations, such as traditions and customs.'));
  soc07.push(mc('error check', 'A student writes: "A society is a place where people share the same traditions and values." What is wrong with this definition?', 'It describes culture, not society', ['Nothing, because it defines society fully', 'It describes a social issue', 'It describes individualism'], 'Shared traditions and values define culture. A society is a large group of people living in the same area with shared rules and laws.'));
  soc07.push(mc('error check', 'Which answer would <b>not</b> earn a mark when asked to define culture?', 'The place where a group of people live', ['Shared customs and traditions of a group', 'The values and beliefs shared by a group', 'The way of life of a group that is passed on'], 'A place is not a definition of culture. Culture is about the shared beliefs, values and customs of a group.'));
  soc07.push(ms('culture knowledge', 'Select <b>all</b> the statements that are true.', ['Collectivist cultures value group harmony', 'Individualist cultures value independence', 'Culture can affect how much people conform'], ['Society and culture are the same thing', 'Research from the USA applies to every culture'], 'Culture values differ between individualist and collectivist cultures, and these differences can affect conformity. Society and culture are different, and findings from one culture do not always generalise.'));
  soc07.push(ms('social issues', 'Select <b>all</b> the examples of a social issue.', ['Crime', 'Prejudice', 'Mental health problems'], ['A person\'s favourite sport', 'An argument between two neighbours over a fence'], 'Social issues affect many people in a society, such as crime, prejudice and mental health. Personal preferences and one-off disagreements are not social issues.'));
  soc07.push(mc('individualist/collectivist application', 'Chen moves from a collectivist country to an individualist country. At first he finds it strange that classmates openly disagree with the teacher. Which statement best explains this?', 'His home culture values group harmony more than independence', ['His new culture has no norms of behaviour', 'He has never been in a society before', 'People in his new country are less intelligent than people in his home country'], 'Chen\'s culture stresses group harmony, so open disagreement feels unusual. It shows how culture shapes expectations about behaviour.'));
  soc07.push(mc('use of research', 'Why is it useful to know that culture can affect conformity?', 'It shows that studies done in one culture may not give the same results elsewhere', ['It proves that conformity is a bad thing', 'It shows that all people conform in the same way', 'It shows that culture has no effect on behaviour'], 'Culture differences in conformity warn psychologists not to assume results from one culture apply to all.'));
  soc07.push(mc('define society', 'A student defines society as "people". Why does this answer not earn the mark?', 'It does not mention living in the same area and sharing rules and laws', ['It is too long', 'It describes culture, not society', 'It only describes an individual'], 'A society is a large group of people who live in the same area and share rules, laws and norms. "People" is too vague.'));
  soc07.push(mc('compare cultures', 'Aliyah says: "Because I come from a collectivist culture, my first thought is to think about what is best for my family." Which statement best fits her view?', 'Duty to the group comes before personal goals', ['Personal goals come before duty to the group', 'Rules and laws do not matter', 'She is not influenced by culture when she thinks about her family'], 'In collectivist cultures duty to the group and harmony are valued, so thinking of family first fits this culture.'));
  B['PSY-SOC-07'] = { title: 'Culture and society', items: soc07 };

  /* ---------- PSY-SOC-03 Why bystanders do or do not help ---------- */
  var soc03 = [];
  soc03.push(mc('key terms', 'What is the <b>bystander effect</b>?', 'People are less likely to help in an emergency when others are present', ['People always help when they see someone in need', 'People help more when more people are watching', 'People help others only when they are paid to'], 'The bystander effect is when a person fails to help because other people are around.'));
  soc03.push(mc('key terms', 'What is <b>pro-social behaviour</b>?', 'Helpful, positive behaviour that benefits other people', ['Behaviour that causes alarm or distress to others', 'Behaviour that follows the rules of a group', 'Behaviour that only happens in large crowds'], 'Pro-social behaviour includes helping, sharing and comforting, such as stopping to help someone in trouble.'));
  soc03.push(mc('diffusion of responsibility', 'Which situational factor explains why a person may not help when a large crowd of people also sees an emergency?', 'Diffusion of responsibility, because each person feels less responsible', ['Competence, because the person lacks first-aid training', 'Locus of control, because the person has a strongly internal locus of control', 'Empathy, because the person feels sad for the victim'], 'The more people present, the less responsible each person feels (Latané and Darley, 1968). This is diffusion of responsibility.'));
  soc03.push(mc('diffusion of responsibility', 'Nadia sees a boy fall from his bike on a quiet road and stops to help immediately. Ten minutes later at a busy market, she sees a woman collapse but waits, assuming someone else will help. Which situational factor best explains the difference?', 'There were more people at the market, so she felt less personally responsible', ['She felt much more empathy for the victim at the market than she had at the road', 'She was more competent at the market', 'She was in a better mood at the market'], 'The larger crowd at the market spreads responsibility between many people, so each feels less responsible. The number of people is a situational factor.'));
  soc03.push(mc('cost of helping', 'A man is being attacked in the street by two people with weapons. Many passers-by walk on. Which situational factor best explains this?', 'The cost of helping is high because helping is dangerous', ['The passers-by all have an internal locus of control', 'The passers-by are all very similar to the victim being attacked', 'The passers-by have first-aid training'], 'People help less when helping seems dangerous, embarrassing or time-consuming. Here, the danger is a high cost.'));
  soc03.push(mc('cost of helping', 'Ayesha sees a pupil drop all their books but is already late for a job interview, so she hurries past. Which situational factor is shown?', 'The cost of helping, because helping would take time', ['Diffusion of responsibility', 'Locus of control', 'Similarity to the victim'], 'Being short of time raises the cost of helping, so she is less likely to stop.'));
  soc03.push(mc('ambiguity', 'Leo sees a man lying on a park bench. He cannot tell if the man is asleep or ill, and he sees others walking past, so he does nothing. Which situational factor is shown?', 'Ambiguity, because it is unclear whether it is an emergency', ['Competence, because Leo knows first aid', 'Empathy, because Leo cares a lot about the man on the park bench', 'Mood, because Leo is happy'], 'When it is unclear whether help is needed, people wait to see what others do. That is the ambiguity of the situation.'));
  soc03.push(mc('competence', 'Ruth has just completed a first-aid course. When a cyclist crashes near her, she goes straight to help. Which personal factor best explains Ruth\'s behaviour?', 'Competence, because she has the skills to help', ['Diffusion of responsibility, because there were few people', 'Ambiguity, because she was unsure it was an emergency', 'Cost of helping, because it was dangerous'], 'Competence, such as having first-aid training, makes a person more likely to help. It is a personal factor because it is about the helper.'));
  soc03.push(mc('similarity', 'A teenager sees someone being bullied who is wearing the same football shirt as him, and steps in to help. Which personal factor is most likely at work?', 'Similarity to the victim', ['Diffusion of responsibility', 'Ambiguity of the situation', 'Cost of helping'], 'People are more likely to help someone similar to themselves. This is a personal factor.'));
  soc03.push(mc('empathy', 'Imran felt a strong sense of sympathy when he heard a younger child crying alone, and he stopped to comfort her. Which personal factor explains this?', 'Empathy', ['Diffusion of responsibility', 'Ambiguity', 'The number of people present'], 'Empathy (sharing another person\'s feelings) raises helping and is a personal factor.'));
  soc03.push(mc('mood', 'Dana has just heard that she won a place on a sports team. Walking home, she stops to help a stranger carry shopping. Which personal factor best explains this?', 'Her good mood', ['Diffusion of responsibility', 'The ambiguity of the emergency', 'A high cost of helping'], 'Mood is a personal factor: people in a good mood are more likely to help.'));
  soc03.push(mc('locus of control', 'Which statement correctly describes how locus of control can affect bystander behaviour?', 'A person with an internal locus of control feels more able to act, rather than copying others', ['A person with an internal locus of control is swayed by what the crowd does', 'A person with an external locus of control always helps first', 'Locus of control is a situational factor'], 'People with an internal locus of control believe they can influence events, so they feel more able to act. Locus of control is a personal factor.'));
  soc03.push(mc('locus of control', 'Sol feels that events in his life are mostly controlled by luck and other people. He waits to see what the crowd does before helping a fallen cyclist. Which personal factor is this?', 'An external locus of control', ['An internal locus of control', 'Competence', 'Diffusion of responsibility'], 'An external locus of control means feeling events are controlled by outside forces, so the person is swayed by what others do.'));
  soc03.push(ms('personal vs situational', 'Select <b>all</b> the <b>situational</b> factors.', ['Diffusion of responsibility', 'The cost of helping', 'Ambiguity of the situation'], ['Competence', 'Empathy'], 'Situational factors are about the setting: number of people, cost and ambiguity. Competence and empathy are about the helper, so they are personal.'));
  soc03.push(ms('personal vs situational', 'Select <b>all</b> the <b>personal</b> factors that make helping more likely.', ['Competence, such as first-aid training', 'Similarity to the victim', 'A good mood'], ['Many other people present', 'A dangerous situation'], 'Personal factors are about the person who may help. The number of people and danger are situational factors.'));
  soc03.push(mc('classify the factor', 'Which of the following is a <b>personal</b> factor affecting bystander intervention?', 'The helper\'s mood', ['The number of other people present', 'The cost of helping', 'How unclear the emergency is'], 'Mood is about the person, so it is personal. The others are features of the situation.'));
  soc03.push(mc('classify the factor', 'Which of the following is a <b>situational</b> factor affecting bystander intervention?', 'The number of people who are present', ['The helper\'s empathy', 'The helper\'s competence and skills at first aid', 'The helper\'s locus of control'], 'The number of people present is about the situation, not the helper.'));
  soc03.push(mc('best explanation', 'A student passes a girl crying on a busy station platform with dozens of commuters around. He does not help. Which is the best explanation using a situational factor?', 'Diffusion of responsibility: with so many people around, each felt less responsible for helping her', ['The student is selfish, so he does not help', 'Diffusion of responsibility is a situational factor', 'The student had low empathy, which is a personal factor'], 'A full answer names the factor, explains how it works, and links it to the scenario (the busy platform). The other options either give no explanation or name a personal factor.'));
  soc03.push(mc('best explanation', 'Which is the best explanation of why Marta, a trained nurse, helped a collapsed man in the street?', 'She has medical competence, which is a personal factor that makes her feel able to help', ['She helped because she is a nice person', 'There were many people present on the street, so she felt less responsible for helping', 'The situation was ambiguous, so she helped without thinking'], 'Competence is a personal factor linked to the helper\'s skills. A full answer links it to the nurse\'s training.'));
  soc03.push(mc('error check', 'A question asks for a <b>situational</b> factor that could explain why Greg did not help. Which answer is wrong?', 'Greg has an external locus of control, so he followed the crowd', ['There were many people near, so Greg felt less responsible', 'Helping would have meant stepping into a dangerous fight', 'Greg could not tell whether the situation was an emergency'], 'Locus of control is a personal factor, not a situational one. The others are situational.'));
  soc03.push(mc('error check', 'A question asks for a <b>personal</b> factor that could explain why Hira helped. Which answer is wrong?', 'Hira helped because the road was nearly empty', ['Hira has first-aid training from a course she completed', 'Hira felt sorry for the victim', 'Hira was in a good mood that day'], 'The number of people nearby is a situational factor. Training, empathy and mood are personal factors.'));
  soc03.push(mc('effect of audience', 'Why are bystanders sometimes <b>less</b> likely to help when more people are present?', 'Each person feels less personally responsible for helping', ['Each person has less empathy', 'Each person is more competent', 'Each person is certain that it is an emergency and that they must act'], 'This is diffusion of responsibility. The more people present, the less responsible each person feels.'));
  soc03.push(mc('explain with detail', 'Why is the answer "Diffusion of responsibility" on its own not enough to gain full marks in an explain question?', 'It also needs an explanation of how it works and a link to the scenario', ['It is a personal factor, so it is wrong', 'It can only be used in an exam question about crowds, not about bystanders', 'It needs a named study as well'], 'Explain answers give the factor, say how it affects helping, and then use details from the scenario.'));
  soc03.push(mc('ambiguity vs diffusion', 'Which situation is best explained by <b>ambiguity</b> rather than diffusion of responsibility?', 'A person alone sees smoke and cannot tell if it is a fire or a barbecue, so waits before acting', ['A person in a crowd assumes someone else will call an ambulance', 'A person walks past a victim because helping is dangerous', 'A person is trained to help and steps in at once'], 'Ambiguity is when it is unclear whether help is needed, which can happen even when alone. Diffusion needs other people present.'));
  B['PSY-SOC-03'] = { title: 'Why bystanders do or do not help', items: soc03 };

  /* ---------- PSY-SOC-06 Crowds, deindividuation, pro-social and anti-social behaviour ---------- */
  var soc06 = [];
  soc06.push(mc('define deindividuation', 'Which statement best defines <b>deindividuation</b>?', 'Losing your sense of personal identity in a group or through anonymity and behaving differently from usual', ['Not helping someone because you think others around you will', 'Blaming other people for your actions', 'Refusing to do something when an authority figure tells you to'], 'Deindividuation means losing a sense of individual identity, for example in a crowd or when anonymous. The other options describe bystander effect, blame-shifting and disobedience.'));
  soc06.push(mc('define pro-social', 'Which is the best definition of <b>pro-social behaviour</b>?', 'Positive behaviour that helps other people or society', ['Behaviour that harms others or breaks social norms', 'Behaviour that follows an order from an authority figure', 'Behaviour that happens only when a person is alone'], 'Pro-social behaviour helps others, for example sharing, helping and comforting.'));
  soc06.push(mc('define anti-social', 'Which is the best definition of <b>anti-social behaviour</b>?', 'Behaviour that harms others or goes against social norms, causing alarm, distress or harassment', ['Behaviour of a person who is shy and avoids other people', 'Behaviour that is not liked by the person doing it', 'Behaviour that happens in a group of more than two people'], 'Anti-social behaviour harms or upsets other people, such as vandalism or noise at night. It does not mean being shy.'));
  soc06.push(mc('error check', 'A student writes: "Anti-social behaviour is when a person is quiet and does not like meeting people." What is wrong with this?', 'Anti-social behaviour means harmful or alarming behaviour towards others, not shyness', ['Nothing, because anti-social means not being social', 'It is pro-social behaviour, not anti-social behaviour', 'It is only anti-social behaviour if it happens in a crowd'], 'A common error is to think that anti-social means shy. In psychology it is behaviour that harms others or causes distress.'));
  soc06.push(mc('pro vs anti examples', 'Which of these is an example of <b>pro-social</b> behaviour?', 'Collecting money for a charity at school', ['Writing graffiti on a bus shelter', 'Shouting abuse at a referee', 'Playing loud music late at night in a flat'], 'Collecting money for others helps society. The other options cause harm, alarm or distress.'));
  soc06.push(mc('pro vs anti examples', 'Which of these is an example of <b>anti-social</b> behaviour?', 'Smashing the windows of a parked car', ['Helping an older neighbour with shopping', 'Comforting a friend who is upset', 'Sharing lunch with a new classmate'], 'Damaging property harms others and goes against social norms, so it is anti-social behaviour.'));
  soc06.push(mc('difference', 'Which answer correctly describes the difference between pro-social and anti-social behaviour?', 'Pro-social behaviour helps others, whereas anti-social behaviour harms or upsets them', ['Pro-social behaviour takes place alone, whereas anti-social behaviour takes place in crowds', 'Pro-social behaviour is always obedient, whereas anti-social behaviour is disobedient', 'Pro-social behaviour harms others, whereas anti-social behaviour helps them'], 'A difference needs both terms and a contrast: pro-social benefits others, anti-social harms or distresses them.'));
  soc06.push(mc('deindividuation scenario', 'At a night-time carnival, people in masks and identical costumes begin to throw things at shop windows, though most would never normally do this. Which term best explains the change in their behaviour?', 'Deindividuation', ['Obedience', 'The bystander effect', 'Pro-social behaviour'], 'Masks and uniform costumes provide anonymity, so people lose their personal identity and may behave differently from usual.'));
  soc06.push(mc('factors', 'Which two factors increase deindividuation in a crowd?', 'Anonymity, such as wearing masks, and a large crowd size', ['Being known by name to people around you and in a small group', 'Being asked to take responsibility and a small group', 'Strong personal identity and being alone'], 'Masks, uniforms or darkness give anonymity, and large crowds make individuals harder to identify. Both increase deindividuation.'));
  soc06.push(ms('factors', 'Select <b>all</b> the situations that are likely to increase deindividuation.', ['Wearing a mask or uniform', 'Being in the dark where nobody can see your face', 'Being part of a very large crowd'], ['Wearing a name badge', 'Being asked by a leader to remember you are personally responsible'], 'Anonymity and large crowds increase deindividuation. Being identifiable or reminded of responsibility reduce it.'));
  soc06.push(mc('crowd types', 'Which of these is an example of a crowd behaving in a <b>pro-social</b> way?', 'A peaceful march to raise money for a children\'s hospital', ['A crowd smashing shop windows after a match', 'A crowd shouting abuse at the rival team and their supporters', 'A crowd of people ignoring a person who has collapsed'], 'A peaceful fundraising march helps others, so it is pro-social. Crowds can also be anti-social, such as riots.'));
  soc06.push(mc('crowd types', 'Which statement about crowds is correct?', 'Crowds can be pro-social or anti-social, depending on the group\'s norms and its leaders', ['Crowds are always anti-social because people lose their identity', 'Crowds are always pro-social because people support each other', 'Crowds never change the way that individuals behave, because everyone in them acts alone'], 'The norms of the crowd and its leaders shape whether it behaves in a pro-social or anti-social way.'));
  soc06.push(mc('leader in crowd', 'Before a student march starts, the union president asks everyone to stay calm and warns that marchers will be recognised from the photographs, so each person will be accountable for their own actions. How is this most likely to affect the crowd?', 'It will help keep the crowd peaceful', ['It will make the crowd more anonymous and so more violent', 'It will have no effect on the crowd\'s behaviour', 'It will turn pro-social behaviour into anti-social behaviour'], 'A leader who calls for calm and reminds people they are accountable reduces deindividuation and encourages peaceful, pro-social behaviour.', { family: 'soc06march' }));
  soc06.push(mc('leader in crowd', 'At a festival, a group leader tells the crowd that the security guards are enemies and urges them to rush the barriers. What is the most likely effect?', 'The crowd may become anti-social, as the leader sets a harmful norm', ['The crowd will stay calm, because people have a strong sense of identity', 'The crowd will behave pro-socially, because a leader is present', 'The crowd will not be affected, because a crowd has no norms'], 'Leaders help set the norms of a crowd. A leader who encourages harmful action may lead the crowd to behave anti-socially.'));
  soc06.push(mc('apply crowd', 'A crowd of supporters in matching scarves gathers outside a theatre to cheer a performer. The organiser keeps asking people to look after each other. Which description fits the crowd best?', 'A pro-social crowd, kept calm by a leader who sets helpful norms', ['An anti-social crowd, because matching scarves cause anonymity', 'An anti-social crowd, because it is large', 'An anti-social crowd, because crowds always become violent'], 'A leader who encourages looking after each other sets pro-social norms. Matching clothes alone do not make a crowd anti-social.'));
  soc06.push(mc('apply deindividuation', 'Which scenario is the best example of <b>deindividuation</b>?', 'A normally polite person posts cruel messages from an anonymous account', ['A person does not help because many others are nearby', 'A person refuses to carry out an instruction from a manager at their workplace', 'A person blames a friend for something they did'], 'Anonymity makes a person feel less identifiable, so they behave differently than usual. That is deindividuation.'));
  soc06.push(mc('confusion check', 'A student says: "Deindividuation is when people do not help because others will." Which term has the student confused it with?', 'The bystander effect (diffusion of responsibility)', ['Obedience', 'Conformity', 'Pro-social behaviour'], 'Not helping because others are present is the bystander effect. Deindividuation is about losing personal identity.'));
  soc06.push(mc('confusion check', 'Which pair is correctly matched?', 'Deindividuation: loss of personal identity in a group', ['Bystander effect: following the orders of an authority figure', 'Obedience: losing a sense of who you are', 'Anti-social behaviour: helping others in need'], 'Only the first pair is correct. Obedience is following orders, and the bystander effect is not helping when others are present.'));
  soc06.push(mc('MCQ definition', 'Which option correctly describes <b>deindividuation</b>?', 'A change in how someone acts after losing their sense of identity', ['When someone does not help because they think other people around them will', 'Where a person blames other people for their own actions and mistakes', 'If a person refuses an instruction from an authority figure they are given'], 'Deindividuation is a loss of personal identity that can change behaviour. The other options are bystander effect, blame and disobedience.'));
  soc06.push(mc('explain crowd behaviour', 'A noisy crowd of students in face paint and identical hoodies pushes through a shopping centre, shouting and knocking over displays. Which answer is the best explanation using deindividuation?', 'Face paint and identical clothes make them anonymous, so they feel less personally responsible and act anti-socially', ['They are a large group, so they are being obedient', 'Face paint is anti-social, so they behave badly', 'They are in a crowd, which is a bystander effect'], 'A full answer names the factor (anonymity), says how it works (less personal responsibility) and links it to the scenario.'));
  soc06.push(mc('explain crowd behaviour', 'A crowd waiting for a train after an event stays calm, queues and helps an older man up the steps. A steward calls out, "Please look after each other, we are all in this together." What does this show about crowds?', 'A leader can encourage pro-social behaviour in a crowd', ['Crowds cannot affect individuals\' behaviour', 'Crowds always behave anti-socially unless alone', 'The crowd is more anonymous, so people do what they like'], 'The steward\'s call helps set a pro-social norm. Crowd behaviour can be shaped by norms and leaders.'));
  soc06.push(mc('link to scenario', 'The question asks you to <b>explain</b> why a march of 500 students stayed peaceful after the union president warned that photographs would let each marcher be identified. Which answer links the factor to the scenario?', 'The warning made marchers feel identifiable and accountable, so they were less deindividuated and kept calm', ['Warnings about being identified are a factor affecting crowds', 'Crowds are usually peaceful when there is a march', 'People in a crowd copy others, so everyone stayed calm'], 'A good answer names the factor and uses details from the scenario (the union president, the photographs and being identifiable).', { family: 'soc06march' }));
  soc06.push(mc('example needed', 'A student is asked to define anti-social behaviour and give an example. Which answer would gain <b>full marks</b>?', 'Behaviour that harms others or causes distress, such as vandalising a bus shelter', ['Behaviour that harms others or causes distress', 'Vandalising a bus shelter', 'Behaviour that is not liked, for example shyness'], 'Two marks need an accurate definition and an example. The second and third answers have only an example or a wrong definition.'));
  B['PSY-SOC-06'] = { title: 'Crowds, deindividuation, pro-social and anti-social behaviour', items: soc06 };
})();
